(window.ST=window.ST||{}).stories=[{"id":"atlab_aang","name":"Aang","chapters":[{"id":"atlab_aang_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"atlab_aang","t":"Negoziante! Appa ha recuperato le forze!"},{"a":"atlab_aang","t":"Quindi... immagino sia l'ora dei saluti..."},{"a":"atlab_sokka","t":"Ehi, su col morale! Possiamo tornare quando vogliamo!"},{"a":"atlab_aang","t":"Hai ragione! Ti ricordi la strada, Sokka?"},{"a":"atlab_sokka","t":"Ehm... Ero distratto..."},{"a":"atlab_sokka","t":"C-Comunque... abbiamo cose da fare. Un Avatar non può fermarsi mai!"},{"a":"atlab_sokka","t":"Forza, Momo! Stiamo partendo!"},{"a":"atlab_aang","t":"Momo! Momo...?"},{"a":"atlab_aang","t":"Ti piace qui, vero? D'accordo, va bene."},{"a":"atlab_aang","t":"Negoziante, ti dispiacerebbe tenere d'occhio Momo per un po'?"},{"a":"atlab_aang","t":"Ritornerò a prenderti, Momo. Promesso!"},{"a":"atlab_aang","t":"Andiamo, Sokka. Grazie di tutto, negoziante!"},{"a":"atlab_sokka","t":"Ciao!"},{"a":"atlab_aang","t":"Su, Appa! Andiamo!"}]},{"id":"atlab_aang_01","i":1,"title":"Deviazione fatidica","req":"atlab_aang:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"inn","t":"Mi spiace, non ci ho capito molto. Puoi ripetere la storia dall'inizio?"},{"a":"atlab_aang","t":"Scusa! Ricomincio da capo!"},{"a":"atlab_aang","t":"Sono Aang, l'Avatar."},{"a":"atlab_aang","t":"Io e i miei amici stavamo viaggiando in groppa al mio bisonte volante..."},{"a":"atlab_aang","t":"Durante il volo, abbiamo per forza sbagliato direzione, perché siamo finiti qui!"},{"a":"inn","t":"Quell'enorme bue là fuori? Può volare?"},{"a":"atlab_aang","t":"Sì! Si chiama Appa. È molto amichevole!"},{"a":"inn","t":"Sembra anche molto stanco. Qualcuno vi sta inseguendo, vero?"},{"a":"atlab_aang","t":"Oh, ehm..."},{"a":"inn","t":"Ehi, non preoccupatevi. Sotto il mio tetto, siete al sicuro. Parola del sottoscritto."},{"a":"inn","t":"Sapete che vi dico? Vi piacerebbe restare qui gratuitamente?"},{"a":"atlab_aang","t":"Gratuitamente? Davvero?!"},{"a":"inn","t":"Beh, tanto per cominciare, non credo che quelle strane monete che avete abbiano valore qui."},{"a":"inn","t":"E poi non posso di certo lasciare che dei bambini dormano per strada, no?"},{"a":"atlab_aang","t":"G-Grazie, signor Oscar!"},{"a":"inn","t":"Sembrate seri e competenti, perché in cambio non andate ad aiutare il negoziante?"},{"a":"atlab_aang","t":"Contaci! Grazie mille!"}]},{"id":"atlab_aang_02","i":2,"title":"Dominio del fuoco?","req":"atlab_aang:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"inn","t":"Ehi, Lilu! Vieni a conoscere il mio nuovo amico!"},{"a":"lilu","t":"Ciao! È la prima volta che vedo tatuaggi come i tuoi..."},{"a":"atlab_aang","t":"Sono Aang! Anche per me è la prima volta che vedo un cappello come il tuo!"},{"a":"inn","t":"Su, Aang, mostrale cosa sai fare!"},{"a":"atlab_aang","t":"Intendi... questo?"},{"a":"lilu","t":"C-Come ci sei riuscito? Non ho percepito alcuna magia!"},{"a":"atlab_aang","t":"Dominio dell'aria! Posso anche dominare la terra e l'acqua!"},{"a":"lilu","t":"Incredibile! Aspetta, ora prendo appunti..."},{"a":"lilu","t":"Si tratta del chi? Non ho mai visto nessuno fare qualcosa di simile..."},{"a":"atlab_aang","t":"Esatto! Solo pochi sono in grado di usarlo. Bisogna nascere con questo talento e coltivarlo!"},{"a":"lilu","t":"Hai detto di poter dominare l'aria, la terra e l'acqua... E il fuoco?"},{"a":"atlab_aang","t":"Ah... Io... Non ho ancora imparato come si fa..."},{"a":"atlab_aang","t":"Ho avuto problemi a trovare un maestro che mi insegnasse il dominio del fuoco."},{"a":"lilu","t":"Ah sì? Io conosco un po' di magia del fuoco!"},{"a":"lilu","t":"Non è la stessa cosa, ma potrebbe piacerti vedere come funziona!"},{"a":"atlab_aang","t":"Ah... certo. Grazie, Lilu."}]},{"id":"atlab_aang_03","i":3,"title":"L'ultimo dominatore dell'aria","req":"atlab_aang:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"elderowen","t":"Aang, ragazzo mio. Com'è vivere in città? Ti sta piacendo?"},{"a":"atlab_aang","t":"Anziano Owen! È fantastico! Grazie per la tua ospitalità."},{"a":"elderowen","t":"Figurati. Ma dimmi, ragazzo mio, dove sono i tuoi genitori?"},{"a":"atlab_aang","t":"Ah... Io non... Non ci sono più."},{"a":"atlab_aang","t":"La mia famiglia... tutti i Nomadi dell'Aria sono stati uccisi dalla Nazione del Fuoco."},{"a":"atlab_aang","t":"Sono l'unico sopravvissuto..."},{"a":"elderowen","t":"Cielo! Ti porgo le mie condoglianze, povero ragazzo mio..."},{"a":"elderowen","t":"Se non hai un posto in cui tornare, perché non ti sistemi qui insieme ai tuoi amici?"},{"a":"elderowen","t":"Sono sicuro che tutti in città sarebbero entusiasti di avervi qui. Siete già molto popolari!"},{"a":"atlab_aang","t":"Grazie per la generosa offerta, anziano Owen... ma non posso accettare."},{"a":"atlab_aang","t":"Mentre parliamo, il signore del fuoco Ozai sta già pianificando la sua prossima mossa."},{"a":"atlab_aang","t":"Quando la Cometa di Sozin illuminerà di nuovo il cielo, la Nazione del Fuoco conquisterà il mondo..."},{"a":"atlab_aang","t":"Il Regno della Terra... le Tribù dell'Acqua... andranno incontro alla stesso destino dei Nomadi dell'Aria."},{"a":"atlab_aang","t":"In quanto Avatar, sono l'unico che può fermarlo! Ma... non sono pronto."},{"a":"elderowen","t":"Che terribile fardello da portare per un bambino..."},{"a":"elderowen","t":"Voglio che tu sappia che qualsiasi cosa accada puoi contare sul pieno sostegno della nostra città."},{"a":"atlab_aang","t":"Grazie, anziano Owen. Tutti voi avete già fatto così tanto per noi!"},{"a":"atlab_aang","t":"Quando tutto sarà finito, non mancheremo di farvi visita!"}]},{"id":"atlab_aang_04","i":4,"title":"La profezia di Sozin","req":"atlab_aang:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"mana","t":"Avatar. Le nostre strade si incrociano ancora."},{"a":"atlab_aang","t":"Chi sei? Come fai a conoscermi?"},{"a":"mana","t":"La presenza dell'Avatar brilla come un faro per il terzo occhio."},{"a":"atlab_aang","t":"Oh, chiaroveggenza... No, grazie!"},{"a":"mana","t":"Tu, che sei molteplice eppur incompleto tuttavia..."},{"a":"mana","t":"Una dura battaglia con il signore del fuoco ti attende lungo la via."},{"a":"atlab_aang","t":"Il signore del fuoco Ozai... Lo conosci?"},{"a":"mana","t":"Sotto lo sguardo della Cometa, la terra si sgretolerà e dei campi non resterà che cenere!"},{"a":"atlab_aang","t":"Lo so! Ma cosa dovrei fare?"},{"a":"mana","t":"Lo scorrere del fato non può essere interrotto."},{"a":"atlab_aang","t":"..."},{"a":"mana","t":"Ma gli impavidi possono riuscire a deviarlo."},{"a":"mana","t":"E un improbabile alleato e una fragile alleanza possono essere la soluzione."},{"a":"atlab_aang","t":"Grazie, chiaroveggente... Penserò alle tue parole."},{"a":"mana","t":"..."},{"a":"mana","t":"Sii coraggioso, Avatar. Rimani fedele a te stesso e prevarrai."}]}]},{"id":"argon","name":"Argon","chapters":[{"id":"argon_01","i":1,"title":"L'ombra del re","req":"argon:1","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"...Ed è stato allora che ho infilzato il goblinello con la mia spada! Zac!"},{"a":"elderowen","t":"Oh oh! Che bella storia, Argon!"},{"a":"elderowen","t":"Ah, lo slancio giovanile..."},{"a":"elderowen","t":"Devo ammettere che è molto gentile da parte tua accompagnare questo povero vecchio durante la sua passeggiata mattutina."},{"a":"argon","t":"Non dirlo nemmeno! Se voglio diventare cavaliere un giorno, aiutare le persone in difficoltà è un dovere morale!"},{"a":"elderowen","t":"Proprio come tuo padre, eh? Sono certo che sarai un ottimo cavaliere, ragazzo mio."},{"a":"elderowen","t":"Magari potresti perfino entrare nella guardia reale!"},{"a":"elderowen","t":"Parli del diavolo e spuntano le corna... eccolo lì, al mercato! Perché non lo chiediamo a lui?"},{"a":"argon","t":"SUA MAESTÀ! Sono venuto a offrirvi i miei servigi di cavaliere!"},{"a":"king","t":"C-Cosa significa tutto questo? Sia, ti prego di occuparti di questo plebeo!"},{"a":"sia","t":"Ma certo, mio re."},{"a":"sia","t":"Beh, giovanotto? Che storia è questa?"},{"a":"argon","t":"Wow! Io, ehm..."},{"a":"argon","t":"Mi chiamo cavaliere! Voglio diventare un Argon!"},{"a":"argon","t":"No, un momento..."},{"a":"sia","t":"Ne hai di fegato!"},{"a":"sia","t":"Se sei davvero così determinato, vieni a incontrarmi nel cortile del castello la settimana prossima."},{"a":"sia","t":"Allenati duramente fino ad allora! Non ammetterò un fannullone fra le guardie del re..."}]},{"id":"argon_02","i":2,"title":"Sequenza d'allenamento","req":"argon:2","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Argon, che ci fai qua fuori?"},{"a":"argon","t":"Mi sto allenando duramente! Finalmente ho l'opportunità di diventare un cavaliere del re!"},{"a":"lilu","t":"Del re? ...O della sua misteriosa consigliera, Sia?"},{"a":"argon","t":"È il suo nome? Anche questo è bellissimo!"},{"a":"lilu","t":"..."},{"a":"argon","t":"Bah! No, no! Mi importa solo del re!"},{"a":"argon","t":"Devo diventare un cavaliere! Non conta nient'altro!"},{"a":"lilu","t":"D'accordo... ecco, lascia che curi le tue ferite."},{"a":"argon","t":"Grazie... ahi! Questo incantesimo brucia!"}]},{"id":"argon_03","i":3,"title":"Le due facce di una moneta","req":"argon:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"Ok! Sia dovrebbe apparire da un momento all'altro!"},{"a":"argon","t":"Il mio addestramento ha dato i suoi frutti, sono pronto!"},{"a":"argon","t":"Ma sono ancora troppo nervoso..."},{"a":"argon","t":"Oh! Ehi, laggiù! Tu, nei cespugli!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Anche tu sei venuta qui per diventare un cavaliere?"},{"a":"argon","t":"Sia arriverà presto! Non c'è bisogno di nasconderti, guarda che è molto gentile!"},{"a":"yami","t":"Sia...!"},{"a":"yami","t":"Devo andare. Arrivederci."},{"a":"argon","t":"A-aspetta!"},{"a":"argon","t":"Wow! Una bomba di fumo?!"},{"a":"argon","t":"Che strana ragazza..."},{"a":"sia","t":"Giovanotto, con chi stai parlando?"},{"a":"argon","t":"Ah, Sia! Solo una timida passante! Non farci caso!"},{"a":"sia","t":"Capisco. Bene allora, sembra che tu non abbia vacillato nella tua decisione."},{"a":"sia","t":"Sei pronto a rischiare la tua vita come cavaliere del re?"},{"a":"argon","t":"Puoi scommetterci! V-volevo dire, certamente! Renderò fiero mio padre!"},{"a":"sia","t":"Bene. Come primo incarico, c'è un importante evento in arrivo..."}]},{"id":"argon_04","i":4,"title":"A mani vuote","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"..."},{"a":"sia","t":"Vorrai scherzare!"},{"a":"sia","t":"Hai messo l'assassina con le spalle al muro... e non sei riuscito a fermarla?"},{"a":"sia","t":"Non solo, mi stai dicendo che L'HAI LASCIATA ANDARE perché pensi che sia una brava persona?!"},{"a":"argon","t":"..."},{"a":"sia","t":"Che sciocchezza è mai questa?"},{"a":"sia","t":"TI RENDI CONTO che quest'assassina ha tentato di uccidere il nostro re, l'uomo che hai giurato di proteggere?"},{"a":"sia","t":"Un simile incidente mette a repentaglio molto più di quanto la tua misera mente riesca a immaginare."},{"a":"sia","t":"Ugh... il re ha l'ultima parola sull'esonero dei propri cavalieri..."},{"a":"sia","t":"Ma non aspettarti che io metta una buona parola per te. Puoi andare."},{"a":"argon","t":"..."},{"a":"argon","t":"Oh cielo...."},{"a":"argon","t":"Mi spiace, papà."}]},{"id":"argon_a","i":4,"title":"La torre dei titani","req":"argon:4","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"elderowen","t":"La torre dei titani, eh?"},{"a":"lilu","t":"Raccontaci tutto!"},{"a":"argon","t":"Alcuni eroi ne sussurrano il nome, ma nessuno l'ha mai vista davvero..."},{"a":"elderowen","t":"Sì, la torre dei titani è un luogo mitico, la cui esistenza non è stata provata."},{"a":"elderowen","t":"Si narra che appaia dal nulla, sfidando gli eroi più arditi a scalarne i numerosi piani..."},{"a":"elderowen","t":"... per poi svanire all'improvviso, cancellando i ricordi di chiunque possa averla vista."},{"a":"argon","t":"C-Cancellando i ricordi?!"},{"a":"lilu","t":"Che strano... Ma da dove provengono le leggende, allora?"},{"a":"argon","t":"Giusto! Qualcuno dev'essere riuscito a ricordarsene!"},{"a":"elderowen","t":"Si dice che chi supera la sfida dei titani viene giudicato degno dalla torre."},{"a":"elderowen","t":"Questi eroi riescono a fare ritorno... L'esperienza li ha cambiati, ma conservano i loro ricordi."},{"a":"elderowen","t":"Per essere più precisi, una parte di loro rimane nella torre e una parte della torre rimane con loro."},{"a":"elderowen","t":"Non ho altro da raccontarvi per oggi. Grazie per aver ascoltato le storie di un povero vecchio."},{"a":"lilu","t":"Wow! Chissà se esiste davvero!"},{"a":"argon","t":"Già! Mi piacerebbe esplorare un posto del genere!"},{"a":"lilu","t":"C'è qualcosa che non mi torna, però... Come fa Owen l'anziano a sapere queste cose?"},{"a":"argon","t":"...!"}]},{"id":"argon_05","i":5,"title":"Cavaliere errante","req":"argon:5","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"Sigh..."},{"a":"steel","t":"Ma guarda, è proprio Argon! Come stai?"},{"a":"argon","t":"Ciao Brohm... Hai qualche lavoretto per me?"},{"a":"steel","t":"Niente per oggi, ser cavaliere! Perché quel muso lungo?"},{"a":"argon","t":"Sono semplicemente Argon, adesso. Io ho... perso il mio titolo."},{"a":"steel","t":"Oh, mi dispiace tanto..."},{"a":"steel","t":"Qualunque cosa accada, non scoraggiarti! Ce la farai!"},{"a":"steel","t":"Vedrai che le cose gireranno presto per il verso giusto!"},{"a":"argon","t":"Hai ragione... Grazie, Brohm."},{"a":"argon","t":"Se hai bisogno di me, mi troverai in piazza."},{"a":"argon","t":"Sigh..."}]},{"id":"argon_b","i":5,"title":"Siamo forse titani?","req":"argon:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"lilu","t":"Buongiorno, Argon."},{"a":"argon","t":"Yawn... 'giorno."},{"a":"lilu","t":"Hai anche tu la stessa sensazione, vero?"},{"a":"argon","t":"Sì, sono distrutto! Mi sembra di essere stato in missione tutta la notte!"},{"a":"lilu","t":"Guarda! Il tuo scudo è tutto scheggiato!"},{"a":"argon","t":"Eh? Hai ragione! Giuro che ieri era come nuovo di zecca..."},{"a":"lilu","t":"Argon... Pensi che...?"},{"a":"polonia","t":"Ahrrr! A qualcuno di voi marinai d'acqua dolce possono interessare degli <c1>schinieri del colosso</c1>?"},{"a":"lilu","t":"No... e soprattutto non 20 paia! Dove hai preso tutta quella roba?"},{"a":"polonia","t":"Ah! Bella domanda. Non ne ho idea."},{"a":"polonia","t":"Forse vado a caccia di bottino nel sonno. Il mio spirito pirata non dorme mai!"},{"a":"lilu","t":"Anche quella bizzarra signora pirata..."},{"a":"lilu","t":"Possibile che abbiamo affrontato tutti la torre e i nostri ricordi siano stati cancellati?"},{"a":"argon","t":"Significa che non siamo stati forti abbastanza..."},{"a":"argon","t":"Mi allenerò senza sosta per la prossima volta! Lo giuro!"}]},{"id":"argon_06","i":6,"title":"Seconda luce","req":"argon:6","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"Insomma quel tizio, quel \"cavaliere\", aveva in pugno la tua assassina..."},{"a":"sia","t":"Ma si è convinto che fosse una brava persona e l'ha lasciata andare!"},{"a":"king","t":"Una storia affascinante! Questo nuovo cavaliere sembra un soggetto promettente!"},{"a":"sia","t":"Con il dovuto rispetto, mio re..."},{"a":"sia","t":"Quest'uomo ha lasciato libera un'assassina sulla base di una sensazione."},{"a":"king","t":"È il tratto distintivo di un <c1>Paladino</c1>, non credi?"},{"a":"sia","t":"Come, scusi?"},{"a":"king","t":"Avere il nemico alla tua mercé, eppure riuscire a guardare oltre il conflitto e l'ostilità..."},{"a":"king","t":"...E lasciarlo andare, così certo della sua redenzione da essere disposto a rischiare il tuo titolo per questo."},{"a":"king","t":"Un atto di coraggio e generosità senza pari!"},{"a":"sia","t":"Io... devo ammettere che non avevo considerato le cose da questo punto di vista, mio re."},{"a":"sia","t":"Ma sono decenni che non si vede un aspirante Paladino nel regno..."},{"a":"sia","t":"Vuole che convochi il consiglio dei cavalieri per discutere la questione?"},{"a":"king","t":"Sciocchezze! Sbrigherò io stesso le formalità."},{"a":"sia","t":"Come desidera, mio re. Appronterò subito una scorta."},{"a":"king","t":"Non è necessario. Sarò furtivo e silenzioso come un topolino!"}]},{"id":"argon_07","i":7,"title":"L'insospettabile re","req":"argon:7","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"king","t":"Fate largo, villici! Un lavoratore come tanti cammina fra voi!"},{"a":"tavern","t":"Ah, re Reinhold! Ne è passato di tempo! Posso offrirvi un bel boccale di ambrosia?"},{"a":"king","t":"Shhh! Sono qui in incognito! Non rivolgerti a me così!"},{"a":"tavern","t":"Oh, certamente! Come ho potuto non capirlo!"},{"a":"king","t":"Ehi, tu! Sì, dico a te dietro al bancone!"},{"a":"argon","t":"Chiedo scusa, vostra maestà! Tolgo subito il disturbo..."},{"a":"king","t":"Che assurdità! Un aspirante paladino ha ogni diritto di sedere al mio regale fianco!"},{"a":"argon","t":"Sedere al... Come? Paladino?"},{"a":"king","t":"Esatto! Nella mia infinita saggezza, ho percepito grande potenziale in te!"},{"a":"king","t":"A onta dei tuoi... metodi non convenzionali, il tuo cuore è puro e il tuo senso della giustizia è ammirevole!"},{"a":"king","t":"Il regno ti ritiene più che degno di affrontare la prova del paladino!"},{"a":"argon","t":"Una prova del paladino... Wow!"},{"a":"argon","t":"Le conosco fin da bambino! Non sono mai uguali fra loro e vengono decise dal paladino stesso..."},{"a":"argon","t":"Deve consistere in un'impresa pericolosa, come sconfiggere un drago o distruggere un pericoloso artefatto..."},{"a":"king","t":"Proprio così! Andrà bene qualsiasi atto coraggioso e altruista che sia compiuto in nome del regno!"},{"a":"argon","t":"Ho capito perfettamente! Grazie, vostra maestà! Non ve ne pentirete!"},{"a":"king","t":"Certo che no, io non mi sbaglio mai!"},{"a":"king","t":"E adesso, già che sono qui in incognito..."},{"a":"king","t":"Ehi tu! Vecchio! Insegnami a giocare a carte!"},{"a":"master","t":"Carte, eh? Attenzione, il vecchio Theodore gioca solo se le puntate sono consistenti..."}]},{"id":"argon_08","i":8,"title":"Riscatto","req":"argon:8","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Argon! Cos'è questa fretta?"},{"a":"argon","t":"Lilu, diventerò un paladino!"},{"a":"lilu","t":"Un paladino!!! Argon, è fantastico! Ma come...?"},{"a":"argon","t":"Il re mi ha detto che affronterò una prova! È l'unico modo di mostrarmi degno del titolo di paladino."},{"a":"lilu","t":"Una prova... Sai già in cosa consisterà?"},{"a":"argon","t":"..."},{"a":"argon","t":"Oh no! Non ne ho idea!"},{"a":"argon","t":"Sarà qualcosa di epico e glorioso..."},{"a":"lilu","t":"Ma Argon, tu hai già compiuto imprese gloriose! Hai sconfitto mostri d'ogni sorta..."},{"a":"argon","t":"Sì, ma dev'essere qualcosa di ancor più grande..."},{"a":"argon","t":"Ho sentito parlare di demoni piumati sul Picco Gugliatetra, forse potrebbero andare..."},{"a":"lilu","t":"Di qualsiasi cosa si tratterà, sono certa che te la caverai benissimo!"},{"a":"argon","t":"Grazie, Lilu... Anche quando non ero più un cavaliere, non hai mai smesso di credere in me..."},{"a":"lilu","t":"Oh! N-Non devi ringraziarmi!"},{"a":"lilu","t":"Piuttosto, ti servirà aiuto nella tua missione! Preparerò qualche pergamena di guarigione per te!"},{"a":"argon","t":"Fantastico! Avanti!"}]},{"id":"argon_09","i":9,"title":"Scontro di Gugliatetra (Argon)","req":"argon:9","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"Detesto questo posto!"},{"a":"argon","t":"Sto arrampicandomi senza sosta ma non vedo arpie... Mi sono anche imbattuto in degli assassini!"},{"a":"argon","t":"Somigliavano a quella ragazza ninja, ora che ci penso..."},{"a":"argon","t":"Per fortuna Lilu mi ha dato queste pergamene guaritrici!"},{"a":"argon","t":"Meglio fare una pausa qui."},{"a":"argon","t":"Uh?"},{"a":"yami","t":"Ancora tu."},{"a":"argon","t":"L'assassina del re!"},{"a":"argon","t":"Era destino. Una taglia ben più ricca di quella di un'arpia!"},{"a":"yami","t":"Fatti sotto. Questo posto sarà la tua tomba."}]},{"id":"argon_10a","i":10,"title":"Ritorno trionfale","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"Re Reinhold! Missione compiuta!"},{"a":"king","t":"Eccellente! Quale immonda bestia hai ucciso?"},{"a":"argon","t":"Ehm... A tal proposito..."},{"a":"yami","t":"Salve."},{"a":"king","t":"C-Cosa significa?"},{"a":"sia","t":"Guardie! Arrestateli entrambi!"},{"a":"argon","t":"No! Un attimo! Le cose sono cambiate!"},{"a":"king","t":"D-Davvero?"},{"a":"yami","t":"Sono qui per... chiedere scusa."},{"a":"sia","t":"Mio re, non vorrete crederle..."},{"a":"argon","t":"Garantisco io per lei! Parola di cavaliere!"},{"a":"king","t":"Bene, e sia! Ascolterò cos'ha da dire!"},{"a":"sia","t":"Bah... Temevo che sarebbe finita così."},{"a":"sia","t":"Guardie! Chiamate i rinforzi e tenetela d'occhio!"},{"a":"sia","t":"Argon, aspetta fuori mentre parliamo con questa... intrusa."},{"a":"argon","t":"Obbedisco!"},{"a":"argon","t":"(Ho forse commesso un errore?)"}]},{"id":"argon_10b","i":11,"title":"Redenzione","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"Bah... Non mi ci voleva questa seccatura."},{"a":"argon","t":"Lady Sia! Com'è andata?"},{"a":"sia","t":"Contro ogni pronostico, re Reinhold ha deciso di perdonare la sua aspirante assassina."},{"a":"sia","t":"Io sono più restia a fidarmi, ma è pur vero che ci ha fornito utili informazioni sull'Ordine azumano."},{"a":"argon","t":"M-Ma allora vuol dire che..."},{"a":"sia","t":"Sì, accettiamo la sua resa e le sue scuse."},{"a":"sia","t":"Deve aver patito la fame, ma sta ricevendo le cure necessarie e si riprenderà presto."},{"a":"sia","t":"Per quanto riguarda te, paladino Argon..."},{"a":"argon","t":"P-Paladino?!"},{"a":"sia","t":"Sì. Una cosa è sconfiggere una minaccia, ma riuscire a redimere una nemica giurata del regno..."},{"a":"sia","t":"A quanto pare re Reinhold ci aveva visto giusto, con te."},{"a":"sia","t":"Vai a festeggiare, paladino. Presto sarai molto, molto impegnato!"},{"a":"argon","t":"Lo farò! Grazie!"},{"a":"argon","t":"Papà... Spero tu sia fiero di me."}]},{"id":"argon_epilogue","i":12,"title":"Epilogo","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Paladino?! Ce l'hai fatta, Argon!"},{"a":"argon","t":"Per un attimo ho davvero temuto di aver fallito..."},{"a":"argon","t":"Ma papà aveva ragione. Dovevo solo seguire il mio cuore!"},{"a":"lilu","t":"Ah... ma allora presto ti manderanno in missione al di là del mare?"},{"a":"argon","t":"Non ancora. Lady Sia vuole che insegni agli eroi come diventare paladini."},{"a":"lilu","t":"Ah, meno male! Anche se... faccio fatica a immaginarti nel ruolo di insegnante."},{"a":"lilu","t":"Non sarai impegnatissimo con importanti missioni da paladino?"},{"a":"argon","t":"Farò del mio meglio! Il regno conta su di me!"},{"a":"tavern","t":"Salve, nobile paladino!"},{"a":"tavern","t":"Brohm mi ha detto che sta cercando guanti da fonderia!"},{"a":"argon","t":"Sì! Vado subito!"},{"a":"lilu","t":"Certe cose non cambiano mai, eh?"},{"a":"tavern","t":"Non il nostro Argon!"}]},{"id":"argon_c","i":13,"title":"Scolpito nella pietra","req":"malady:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"argon_stone","t":"..."},{"a":"lilu","t":"La pozione... non ha funzionato, vero?"},{"a":"lilu","t":"Sigh... Dopo tutto il nostro impegno..."},{"a":"lilu","t":"Mi dispiace, Argon. Le mie abilità non sono state all'altezza... Spero tu non stia troppo male là dentro."},{"a":"elderowen","t":"Mh... Davvero una pessima notizia."},{"a":"lilu","t":"Abbiamo ancora qualche opzione, ma..."},{"a":"lilu","t":"... È dura quando non è con noi."},{"a":"elderowen","t":"La città sembra così desolata senza di lui, non credi?"},{"a":"lilu","t":"... Come una festa di compleanno senza amici."},{"a":"lilu","t":"... Non lo riporteremo tra noi piangendoci addosso. Mi rimetto al lavoro."},{"a":"lilu","t":"Forse potremmo chiedere aiuto a Donovan."},{"a":"lilu","t":"Avrà un costo, ma possiamo fare cassa comune!"},{"a":"lilu","t":"So che non ti muoverai di qui, ma... resisti! Ti salveremo!"},{"a":"argon_stone","t":"..."}]}]},{"id":"ashley","name":"Ashley","chapters":[{"id":"ashley_01","i":1,"title":"L'insolita samurai","req":"ashley:1","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"Una vera samurai! Non sto nella pelle!"},{"a":"argon","t":"Signorina samurai! Mi presento, sono Argon, cavaliere in-"},{"a":"ashley","t":"Ohi. Sono Ashley. Come butta?"},{"a":"argon","t":"... Ohi?"},{"a":"tavern","t":"Giù quei piedi dal tavolo, per favore!"},{"a":"ashley","t":"Uff. Va bene."},{"a":"ashley","t":"Beh? Cosa ti serve?"},{"a":"argon","t":"Uh... Ma i samurai non sono tipi formali, di solito?"},{"a":"ashley","t":"Eh? Beh, sì, dalle mie parti i colleghi sono davvero seriosi."},{"a":"ashley","t":"Ma io sono libera, ora. Sono una semplice ronin, una samurai senza padrone."},{"a":"argon","t":"Capisco... Oh, accidenti!"},{"a":"argon","t":"Avevo in programma una missione con Lilu al Castello infestato, ma..."},{"a":"argon","t":"C'è stato un problema alla sala di addestramento! Potresti andare tu al mio posto?"},{"a":"ashley","t":"Certo! Ma sei in debito con me, cavalieruccio."}]},{"id":"ashley_02","i":2,"title":"Pronta per la battaglia","req":"ashley:2","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"ashley","t":"Sei tu Lilu, giusto?"},{"a":"lilu","t":"Proprio così! Piacere di conoscerti!"},{"a":"ashley","t":"Bene, andiamo."},{"a":"lilu","t":"A-Aspetta! Un momento!"},{"a":"lilu","t":"Non abbiamo preparato nulla! Pozioni, cibo e..."},{"a":"ashley","t":"Naaah, non ci serve nulla di quella roba."},{"a":"ashley","t":"Si vive o si muore. Niente vie di mezzo."},{"a":"lilu","t":"Ma... No! Che incoscienza!"},{"a":"ashley","t":"Io vado. È da questa parte, giusto?"},{"a":"lilu","t":"No! Lì ci sono le Foreste ululanti..."},{"a":"argon","t":"Ehm... Buona fortuna?"}]},{"id":"ashley_03","i":3,"title":"Sul filo della lama","req":"ashley:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"ashley","t":"Questo è il meglio che potete fare voi mostri? FATEVI SOTTO!"},{"a":"lilu","t":"Ashley! Sii più cauta! Non riesco a curarti abbastanza in fretta!"},{"a":"ashley","t":"Questo... è... NIENTE!!!"},{"a":"ashley","t":"Fiuuu... È stato divertente, vero?"},{"a":"lilu","t":"Stai scherzando? Stavi per morire!"},{"a":"lilu","t":"Se combatti sempre così, non mi stupisce che tu abbia perso un braccio!"},{"a":"ashley","t":"Ohi. Lì è stato diverso."},{"a":"ashley","t":"Ma è un errore che non ripeterò."},{"a":"lilu","t":"Umpf. Ti guarirò senza anestesia."},{"a":"lilu","t":"La colpa è solo tua. Preparati."},{"a":"ashley","t":"Ah ah... Ah... Non è nulla..."},{"a":"ashley","t":"Ouch! Ahi ahi ahi!"}]},{"id":"ashley_a","i":4,"title":"Tutto in famiglio","req":"ashley:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"ashley","t":"Ohi. Cosa sono tutti questi mostriciattoli?"},{"a":"elven","t":"Sono i miei adorati famigli. Benvenuta!"},{"a":"elven","t":"I campioni più valorosi possono adottarne uno come fedele compagno."},{"a":"ashley","t":"Ah, sono animali domestici. Capito."},{"a":"ashley","t":"Bene, prendo quello verde. Ti chiamerò <c1>Scherzetto</c1>. Vieni con me!"},{"a":"ashley","t":"Sei adorabile, <c1>Palla di neve</c1>. Vieni qui."},{"a":"elven","t":"Ah... Temo che..."},{"a":"ashley","t":"Uh, che uccellaccio!"},{"a":"ashley","t":"Ti chiamerò <c1>Passerotto</c1>. Puoi venire anche tu."},{"a":"elven","t":"... D'accordo. Divertitevi."}]},{"id":"ashley_04","i":5,"title":"Missione Fallita con Successo.","req":"ashley:4","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"Come è andata la missione di ieri? Lilu sembrava piuttosto sconvolta..."},{"a":"ashley","t":"Sono tornata tutta intera. Purtroppo."},{"a":"argon","t":"Eh!? Non è una cosa positiva...?"},{"a":"king","t":"Salve, plebei! Sentitevi liberi di ammirarmi in tutto il mio splendore!"},{"a":"ashley","t":"Ah, signor Re, signore! Ashley a rapporto!"},{"a":"king","t":"Questo sì che è un ottimo esempio di come si fa il soldato! Continua così!"},{"a":"ashley","t":"Sì, signore! Grazie, signore!"},{"a":"tavern","t":"Mi dispiace Reinhold, la tua collezione vintage non è ancora arrivata."},{"a":"king","t":"D'accordo. Tornerò domani!"},{"a":"argon","t":"Che storia è questa?"},{"a":"ashley","t":"Oh, ah. Sono stata a servizio da un lord. Vecchie abitudini."},{"a":"argon","t":"Che bello! Dimmi tutto!"},{"a":"ashley","t":"No."}]},{"id":"ashley_05","i":6,"title":"Svolta del Racconto","req":"ashley:5","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"ashley","t":"... E così ho detto al tizio..."},{"a":"ashley","t":"\"Armata e pronta? Beh, sicuramente sono pronta!\""},{"a":"argon","t":"Ah ah ah!"},{"a":"argon","t":"... Ma Ashley, a proposito di quel lord che hai menzionato prima..."},{"a":"ashley","t":"Ohhh, eddai... Non vuoi proprio mollare l'osso, eh? Va bene."},{"a":"ashley","t":"... I samurai servono un lord che si chiama \"daimyo\". Lo serviamo e lo proteggiamo con la nostra vita."},{"a":"argon","t":"Davvero onorevole!"},{"a":"ashley","t":"Un giorno come tanti altri, stava pranzando come al solito..."},{"a":"ashley","t":"Poi, all'improvviso, boom. Ninja. Ninja ovunque. Tutti... che volevano la testa del mio padrone."},{"a":"ashley","t":"Abbiamo combattuto duramente. Non era la prima volta, ma..."},{"a":"ashley","t":"Ho preso un brutto colpo. Ho perso il braccio."},{"a":"ashley","t":"Poi io... sono scappata. L'ho lasciato lì a morire."},{"a":"argon","t":"Ashley..."},{"a":"ashley","t":"... RAAAAAAAAAAAH!!! Sarei dovuta morire lì con lui!"},{"a":"ashley","t":"... Naya, dammene un altro."},{"a":"tavern","t":"Ne hai già avuti abbastanza per oggi, Ashley."},{"a":"ashley","t":"Va bene. Fa' niente. Sono a posto."},{"a":"ashley","t":"Bene, allora. Argon, vai a dire a Lilu che Ashley sta per intraprendere una missione davvero pericolosa."},{"a":"argon","t":"Uh? Adesso?!"},{"a":"ashley","t":"Ci puoi scommettere. Sto andando alle... diciamo alle Grotte dell'aurora. Meglio sbrigarsi!"}]},{"id":"ashley_06","i":7,"title":"Occhio per me","req":"ashley:6","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"ashley","t":"... Ragazza ninja. Stavi origliando?"},{"a":"yami","t":"... Un po'. Vogliamo parlarne fuori?"},{"a":"ashley","t":"Ah! Non sono dell'umore giusto per combattere."},{"a":"yami","t":"È stato il mio clan a fare questo a lord Kusunoki. Sono una reietta, ma forse le mie scuse..."},{"a":"ashley","t":"Grazie, ma non è necessario. Non è te che odio, bensì me stessa."},{"a":"yami","t":"Capisco... Forse più di quanto tu possa immaginare."},{"a":"yami","t":"Ma anche se il tuo onore è macchiato, hai ancora molto per cui vivere."},{"a":"yami","t":"Qui hai degli amici. Una città che è come una famiglia. Animali domestici che ami."},{"a":"yami","t":"... Ma se ciò non bastasse, posso offrirti un onorevole duello all'ultimo sangue."},{"a":"ashley","t":"Assassinio gratuito da parte di un ninja? Mi vizi troppo."},{"a":"ashley","t":"Grazie, ma passo. Ci penserò, però."},{"a":"yami","t":"Come desideri."}]},{"id":"ashley_07","i":8,"title":"Un Ultimo Scontro","req":"ashley:7","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Uff... Uff... Ashley non è qui..."},{"a":"lilu","t":"Si è persa di nuovo?"},{"a":"lilu","t":"No, un momento. Mi sono lasciata ingannare?"},{"a":"ashley","t":"Pensavo di essere diretta al Vulcano cinereo..."},{"a":"ashley","t":"Va beh, va bene lo stesso."},{"a":"ashley","t":"Ooooohi! Svegliatevi, idioti! Ashley è qui!"},{"a":"monster_Grotto_Mob","t":"L'umana è... ubriaca?"},{"a":"ashley","t":"Oggi niente guaritrici ficcanaso, solo io e il mio desiderio di morte! Non mi fermerò finché non sarò stecchita!"},{"a":"ashley","t":"Qualunque cosa accada, vincerò io! Allora, chi è il primo?"},{"a":"monster_Ruins_Mob","t":"Argh! Dacci dentro!"},{"a":"ashley","t":"Così si fa!"}]},{"id":"ashley_08","i":9,"title":"Deus Ex Asthea","req":"ashley:8","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"priest","t":"Oh, dea... È il posto giusto...?"},{"a":"priest","t":"Santo cielo, che bagno di sangue."},{"a":"monster_Grotto_Mob","t":"Eh eh eh."},{"a":"priest","t":"Perdonatemi, mostri. Vi prego, permettetemi di recuperare la mia compagna."},{"a":"monster_Grotto_Mob","t":"Non è possibile! NON è possibile! Ci ha fregati! Quella samurai è morta stecchita!"},{"a":"priest","t":"È ancora viva. La nostra Ashley è più forte di così."},{"a":"monster_Ruins_Mob","t":"Eh? Allora è meglio che finisca il lavoro!"},{"a":"priest","t":"Non farai nulla del genere."},{"a":"monster_Grotto_Mob","t":"Eh eh ah! Che cosa pensi di FARE? Guarirci?"},{"a":"priest","t":"Non mi lasci altra scelta. Che la dea Asthea ti perdoni."},{"a":"priest","t":"Perché io non lo farò."}]},{"id":"ashley_09","i":10,"title":"Allettamento Forzato","req":"ashley:9","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"ashley","t":"... Ugh..."},{"a":"priest","t":"Finalmente hai ripreso conoscenza."},{"a":"ashley","t":"Eh? Dannazione... non anche tu. Come... mi hai trovata?"},{"a":"priest","t":"Sembra che la Dea ti voglia bene. Sono stata mandata al suo posto."},{"a":"ashley","t":"Dannazione... Dai, lasciami morire."},{"a":"priest","t":"Se è ciò che desideri davvero..."},{"a":"ashley","t":"Ooh... Finalmente..."},{"a":"ashley","t":"..."},{"a":"ashley","t":"... Allora perché stai CONTINUANDO a curarmi?!"},{"a":"priest","t":"Nonostante le tue parole, sembra che tu voglia vivere."},{"a":"priest","t":"La magia curativa semplicemente accelera la tua forza vitale. Se davvero volessi morire, non potrei fare nulla per salvarti."},{"a":"ashley","t":"Ah... sì?"},{"a":"priest","t":"... Riposati per ora. Hai molto a cui pensare."}]},{"id":"ashley_10","i":11,"title":"Un tempo per pensare","req":"ashley:10","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"Sei tornato! Lilu ti ha cercato dappertutto!"},{"a":"argon","t":"...Sembri un po' conciato male, anche tu."},{"a":"ashley","t":"Non farci caso, mi hanno rattoppato. E mi sono preso anche una bella strigliata."},{"a":"argon","t":"Da Freyja? È difficile immaginarlo."},{"a":"ashley","t":"Già. Mi ha detto di iniziare a pensare. Quindi sto pensando."},{"a":"tavern","t":"Pensare? Che novità!"},{"a":"ashley","t":"Smettila."},{"a":"ashley","t":"...è quello che vorrei dire, ma hai ragione."},{"a":"ashley","t":"Sono rimasto bloccato nel passato così a lungo, che mi sono dimenticato di pensare del tutto."},{"a":"argon","t":"Pensare a cosa?"},{"a":"ashley","t":"Mmm. Tante cose."},{"a":"ashley","t":"Senza che me ne accorgessi, sembra di aver raccolto molte cose a cui tenevo."},{"a":"ashley","t":"La città. La gente. Il bottegaio. Anche tu, ragazzo cavaliere."},{"a":"ashley","t":"Mi ci sono voluti solo diversi incontri ravvicinati con la morte per accorgermene. Immagino di essere lento a capire, eh."},{"a":"argon","t":"Sono onorato, signorina Samurai!"},{"a":"ashley","t":"Ancora un Ronin qui. Non aspettarti che cambi presto."},{"a":"yami","t":"..."},{"a":"yami","t":"..."}]},{"id":"ashley_epilogue","i":12,"title":"Epilogo","req":"ashley:11","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"ashley","t":"Ehi, Lilu. Sto per partire per un'altra missione. Vuoi venire con me?"},{"a":"lilu","t":"Umpf! Così potrai mandarmi di nuovo nel posto sbagliato?"},{"a":"lilu","t":"Oppure lanciarti contro i mostri in modo così spericolato da costringermi a ricucirti dopo?"},{"a":"ashley","t":"... No, sono cambiata. Ci andrò piano, con una mano dietro la schiena."},{"a":"lilu","t":"Uhm... Se lo dici tu."},{"a":"lilu","t":"Un momento..."},{"a":"ashley","t":"Ah ah! Scherzaaaavo."},{"a":"ashley","t":"Se tu mi copri le spalle, io coprirò le tue."},{"a":"lilu","t":"A me sta bene! Ma questa volta promettimi che..."},{"a":"lilu","t":"Se le cose si dovessero mettere male... ci ritireremo. TU ti ritirerai."},{"a":"ashley","t":"Promesso. Sul mio onore di ronin. Per quel che vale."},{"a":"ashley","t":"Dopotutto, abbiamo una casa a cui tornare."}]}]},{"id":"bjorn","name":"Bjorn","chapters":[{"id":"bjorn_01","i":1,"title":"Papà è tornato","req":"bjorn:1","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"bjorn","t":"Ciao, piccoli! Papà è tornato!"},{"a":"steel","t":"Papà!"},{"a":"wood","t":"... Papà."},{"a":"bjorn","t":"Come mai quel muso lungo, Gorza?"},{"a":"wood","t":"Sei sparito per MESI!"},{"a":"bjorn","t":"Così è la vita di un esploratore! Nella natura selvaggia, a miglia e miglia da casa."},{"a":"wood","t":"Bah. Potresti anche tornare più spesso."},{"a":"bjorn","t":"Mi piacerebbe, ma purtroppo il Vulcano cinereo mi dà un gran daffare!"},{"a":"wood","t":"Il Vulcano? Ma avevi detto che stavi esplorando il Picco Gugliatetra..."},{"a":"bjorn","t":"Ho detto così?"},{"a":"bjorn","t":"Devo aver fatto confusione! Ahr ahr!"},{"a":"bjorn","t":"Dimenticavo, ho portato dei souvenir per voi! Venite a vedere!"},{"a":"steel","t":"Oh! Spero sia un peluche di Magmy!"}]},{"id":"bjorn_a","i":1,"title":"Bamham il cucciolone","req":"bjorn:1","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"bjorn","t":"Ragazzi, potete badare voi a Bamham per un po'?"},{"a":"wood","t":"Quel cinghiale feroce? Nemmeno per sogno, portalo con te."},{"a":"steel","t":"Non offenderti, papà, ma Bamham è un po'... pazzo."},{"a":"bjorn","t":"Che assurdità! Guardalo, è un cucciolone!"},{"a":"wood","t":"Papà, lascia sempre dietro di sé una scia di morte e distruzione quando lo lasci fare."},{"a":"bjorn","t":"Ehi, quella volta è stato solo un incidente! Era sovraeccitato!"},{"a":"wood","t":"E tutte le altre volte?"},{"a":"bjorn","t":"Beh... altri incidenti! Il piccolo Bamham non farebbe male a una mosca."},{"a":"wood","t":"Lo farebbe eccome, e ci proverebbe anche molto gusto."},{"a":"wood","t":"Papà, ascolta, è meglio se porti quella bestia con te quando sei in città."},{"a":"steel","t":"Per la sicurezza di tutti."},{"a":"bjorn","t":"D'accordo, d'accordo. Non ascoltarli, Bamham. Sei adorabile così come sei."},{"a":"bjorn","t":"Woah, woah! Buono, Bamham, buono!"}]},{"id":"bjorn_02","i":2,"title":"La lista della spesa di Bjorn","req":"bjorn:2","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"bjorn","t":"Grazie a tutti per il caloroso benvenuto! È bello essere di nuovo qui!"},{"a":"elderowen","t":"Siamo felici che tu sia tornato sano e salvo. Dopo tutti questi mesi, iniziavamo a temere il peggio..."},{"a":"bjorn","t":"Mi dispiace, ma purtroppo la vita di un esploratore è così! Ahr ahr!"},{"a":"oils","t":"Immagino che tu stia già pianificando la tua prossima spedizione, non è così?"},{"a":"bjorn","t":"Ahr ahr! Hai fatto centro! Partiremo domani all'alba!"},{"a":"oils","t":"Non cambiare mai, Bjorn. Terrò d'occhio io Brohm e Gorza mentre tu sei via."},{"a":"oils","t":"... Se ti trovi di passaggio, raccoglieresti qualche fungo luminoso per me?"},{"a":"bjorn","t":"Ma certo, non c'è problema!"},{"a":"elderowen","t":"Oh... Ultimamente ho problemi con la schiena, mi aiuteresti molto portandomi delle perle gelide..."},{"a":"bjorn","t":"Dovrei allungarmi solo un po', conta su di me, anziano."},{"a":"engineer","t":"Ehi, Bjorn! Potresti portarmi qualche scaglia di ruggidraco? Mi servirebbero per il mio prossimo esperimento!"},{"a":"bjorn","t":"Certo, Certo! Le aggiungo alla lista!"},{"a":"bjorn","t":"Fiuu! Ci servirà uno zaino bello capiente, Bamham!"}]},{"id":"bjorn_03","i":3,"title":"Aggeggi misteriosi","req":"bjorn:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"bjorn","t":"Mmmh... Annusi quello che annuso io, Bamham?"},{"a":"bjorn","t":"Proprio così... Metallo. L'avrà gettato via qualcuno. Avanti Bam, trovalo e portamelo!"},{"a":"bjorn","t":"Bravo! Vediamo un po'..."},{"a":"bjorn","t":"Uh, che strano apparecchio. Mi sa che non è stato lasciato qui per errore..."},{"a":"bjorn","t":"Scommetto che, se tiro un po' questa manopola qui..."},{"a":"bjorn","t":"Mmmh... Sì, proprio come sospettavo."},{"a":"bjorn","t":"L'ho rotto. Mi sa che non abbiamo scoperto granché, eh? Ahr ahr!"},{"a":"bjorn","t":"Ma ho l'impressione che questa sia la pista che cercavamo da mesi. Questo coso non era qui, l'ultima volta."},{"a":"bjorn","t":"Torniamo indietro e parliamo con qualcuno che ne capisce più di noi, io non vado d'accordo con la tecnologia!"}]},{"id":"bjorn_04","i":4,"title":"Un faro misterioso","req":"bjorn:4","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"engineer","t":"Che oggetto peculiare! Mai visto nulla di simile."},{"a":"engineer","t":"Sembra combinare allo stesso tempo magia e scienza, fungendo quasi come... un faro? Un radar?"},{"a":"engineer","t":"Hai detto che era già rotto quando l'hai trovato?"},{"a":"bjorn","t":"Già. Che sfortuna, eh? Ahr ahr!"},{"a":"engineer","t":"Peccato. L'unica cosa che posso dire con certezza è che può inviare una qualche sorta di informazione."},{"a":"engineer","t":"Se puoi aspettare un minuto, credo di poter costruire un dispositivo che ti aiuterà a trovare altri di questi... \"fari magici\"."},{"a":"bjorn","t":"Fantastico! Pronto a rimetterti in cammino, Bamham?"},{"a":"bjorn","t":"Non sappiamo cosa siano questi cosi... ma di certo non sono nulla di buono."},{"a":"bjorn","t":"Spetta a noi scoprire chi si cela dietro tutto questo!"},{"a":"engineer","t":"Buona fortuna! E ricorda di fare attenzione quando maneggi degli artefatti misteriosi!"}]}]},{"id":"donovan","name":"Donovan","chapters":[{"id":"donovan_01","i":1,"title":"Ricetta originale","req":"donovan:1","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"herbalist","t":"Ti do il benvenuto al Medicamentorium di Maribel. Come posso aiutarti?"},{"a":"donovan","t":"Lady Maribel, giusto? Volevo congratularmi personalmente per la tua ultima creazione."},{"a":"donovan","t":"In quanto inventore della pozione del rinnovo, trovo che il tuo progetto modificato sia puro genio!"},{"a":"donovan","t":"La semplice aggiunta di un pizzico di fiore di Picco brumoso migliora tremendamente la miscela!"},{"a":"herbalist","t":"Aspetta un attimo, vuoi dire che... tu sei QUEL Donovan? Incredibile!"},{"a":"herbalist","t":"Il progetto della pozione del rinnovo risale a circa 700 anni fa..."},{"a":"herbalist","t":"Anche se sei un elfo, ti darei al massimo 150 anni!"},{"a":"donovan","t":"Troppo gentile, lady Maribel."},{"a":"donovan","t":"Diciamo che non tutti i miei progetti sono disponibili sul mercato..."},{"a":"donovan","t":"Ma sono certo che un'alchimista abile come te non farà fatica a impararli."},{"a":"donovan","t":"Ora posso dare un'occhiata a quel fiore di Picco brumoso?"}]},{"id":"donovan_02","i":2,"title":"Terra dell'abbondanza","req":"donovan:2","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"donovan","t":"Affascinante... da queste parti anche le mele sono di qualità eccellente."},{"a":"donovan","t":"Mi chiedo come sia possibile...?"},{"a":"lilu","t":"Juniper avrà sicuramente una spiegazione!"},{"a":"lilu","t":"Oh, mi spiace! Non volevo interrompere la sua conversazione con... l'albero."},{"a":"donovan","t":"Ah, una ragazza con un cappello a tesa larga e il suo fedele gufo..."},{"a":"donovan","t":"Devi essere la signorina Lilu."},{"a":"lilu","t":"Proprio così! E lei non ha bisogno di presentazioni, sir Donovan!"},{"a":"donovan","t":"Ho sentito ottime cose sulla brillante studentessa della città. Il piacere è mio."},{"a":"donovan","t":"Dunque, signorina Lilu. Dicevi...?"},{"a":"lilu","t":"Oh, sì! Juniper parla spesso di quanto la terra attorno al villaggio sia ricca di vita..."},{"a":"lilu","t":"Dice che è uno dei motivi per cui ama così tanto fare giardinaggio qui."},{"a":"lilu","t":"Ora devo andare, le Grotte dell'aurora mi aspettano. È stato bello conoscerla, sir Donovan!"},{"a":"donovan","t":"Mi auguro di rivederti presto."},{"a":"donovan","t":"Uhm... Ciò che dice la ragazza è interessante..."},{"a":"donovan","t":"Possibile che la vitalità di Kern sia ormai prosciugata? In questo regno sembra tutto più vivace e vibrante."},{"a":"donovan","t":"Dovrei fare visita a questa giardiniera. Se qui gli ingredienti sono più potenti..."},{"a":"donovan","t":"Allora devo assolutamente trarne vantaggio."}]},{"id":"donovan_03","i":3,"title":"Dietro la maschera","req":"donovan:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Mi ha chiamato, signorina Sia?"},{"a":"sia","t":"Ah, Lilu. Grazie per essere venuta con così poco preavviso."},{"a":"sia","t":"Hai già avuto modo di conoscere Donovan, non è così?"},{"a":"lilu","t":"Certo! È una leggenda tra gli alchimisti! È stato un onore incontrarlo!"},{"a":"sia","t":"Sii molto prudente quando interagisci con quell'uomo."},{"a":"lilu","t":"Eh? Ma è un perfetto gentiluomo, nonché un vero pozzo di sapere..."},{"a":"sia","t":"L'apparenza può ingannare. Dietro quel volto giovanile si nasconde una mente millenaria e subdola."},{"a":"lilu","t":"Millenaria!? Sarebbe incredibile perfino per un elfo! Credi che..."},{"a":"sia","t":"Sì. Le voci dicono che ha scoperto una sorta di elisir di vita eterna."},{"a":"lilu","t":"Wow! Mi piacerebbe aggiungerne la formula al mio grimorio!"},{"a":"sia","t":"Molti regnanti la pensano come te. Sospetto che l'imperatore di Kern penda dalle sue labbra, ormai."},{"a":"lilu","t":"Uff, la politica è così complicata..."},{"a":"lilu","t":"Ad ogni modo, grazie! Farò attenzione!"},{"a":"sia","t":"Sapevo che avresti capito."},{"a":"sia","t":"Io farò tutto ciò che posso per tenerlo alla larga dal nostro... suggestionabile re."},{"a":"lilu","t":"Già... direi che è il caso."}]},{"id":"donovan_a","i":3,"title":"Un affarone da dieci monete","req":"donovan:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"leather","t":"Ehi, tipo delle pozioni, hai un secondo?"},{"a":"donovan","t":"Ugh... un vagabondo."},{"a":"donovan","t":"A cosa devo il... piacere?"},{"a":"leather","t":"Sono Tamas, quello del cuoio."},{"a":"leather","t":"Ho sentito che fai un elisir di lunga vita da paura, bello. Posso averne una bottiglia?"},{"a":"donovan","t":"Non ho idea di dove tu abbia potuto sentire una simile informazione."},{"a":"donovan","t":"Se anche fosse vero, non regalerei certo in giro qualcosa di tanto prezioso."},{"a":"leather","t":"Ti do dieci monete d'oro in cambio!"},{"a":"donovan","t":"Non scherziamo. Si sono combattute guerre per il possesso di questa formula! Gli imperatori si inginocchiano per averne una singola goccia!"},{"a":"leather","t":"Sei un osso duro, bello. Quindici monete. Ultima offerta."},{"a":"donovan","t":"L'odore del cuoio ti ha bruciato il cervello, vagabondo? Non darei via questa formula nemmeno per tutto l'oro del mondo!"},{"a":"donovan","t":"Devo andare. Non rivolgermi mai più la parola, per favore."},{"a":"leather","t":"Cavolo, era quasi mia."},{"a":"leather","t":"Dovrò trovare un altro regalo per quelle pecore..."}]}]},{"id":"hemma","name":"Hemma","chapters":[{"id":"hemma_01","i":1,"title":"L'ombra incombente","req":"hemma:1","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"hemma","t":"... E così il goblinello andò incontro alla sua fine, ma solo dopo aver ferito i miei compagni."},{"a":"hemma","t":"Ti prego di occuparti di loro."},{"a":"priest","t":"Certamente. Mi prenderò subito cura delle loro ferite."},{"a":"lilu","t":"Ciao! Ho sentito che c'è una nuova incantatrice in città!"},{"a":"lilu","t":"Io sono Lilu, piacere di conoscerti!"},{"a":"hemma","t":"Non ti sbagli, giovane Lilu. Il nostro nome è Hemma. "},{"a":"lilu","t":"... \"Nostro\"?"},{"a":"hemma","t":"Sì. I praticanti della necromanzia pagano un caro prezzo..."},{"a":"hemma","t":"Una parte di te rimane oltre il velo e altre entità ne prendono il posto..."},{"a":"hemma","t":"Questi poteri... ci hanno cambiato. In meglio, ovviamente."},{"a":"lilu","t":"Hai detto necromanzia? Ma non è... pericolosa?"},{"a":"hemma","t":"Molto. Ma non possiamo più accontentarci di meri trucchetti."},{"a":"hemma","t":"Ora, se vuoi scusarci, dobbiamo essere altrove. Arrivederci."},{"a":"lilu","t":"Una necromante... Un'arte magica davvero oscura, Pollux! È la prima volta che vedo di persona qualcuno che la pratica!"},{"a":"lilu","t":"Non sembrava malvagia... Vero?"}]},{"id":"hemma_02","i":2,"title":"Ad ogni costo","req":"hemma:2","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"elderowen","t":"Una necromante?!"},{"a":"elderowen","t":"Non so bene che pensare..."},{"a":"hemma","t":"Capisco le tue preoccupazioni. La necromanzia è un'arte pericolosa che consuma le creature più deboli..."},{"a":"hemma","t":"Ma noi non siamo affatto deboli."},{"a":"elderowen","t":"E gli avventurieri che viaggiano con te? Non prosciughi la loro essenza per potenziare i tuoi incantesimi?"},{"a":"hemma","t":"Solo con il loro consenso, e gli effetti sono temporanei."},{"a":"hemma","t":"Inoltre, li paghiamo profumatamente per i loro servigi."},{"a":"elderowen","t":"Immagino che, tutto sommato, anche tu faccia del bene..."},{"a":"elderowen","t":"Bene, direi che possiamo nominarti uno dei campioni di questa città."},{"a":"hemma","t":"Non ci serviva la tua approvazione... ma grazie."},{"a":"elderowen","t":"Cosa ti ha portato qui?"},{"a":"hemma","t":"..."},{"a":"hemma","t":"Cerchiamo solo conoscenza e potere. "},{"a":"hemma","t":"C'è un... incarico di cui dobbiamo occuparci."},{"a":"elderowen","t":"Piuttosto vago..."},{"a":"hemma","t":"E tale resterà. Arrivederci."},{"a":"elderowen","t":"..."},{"a":"elderowen","t":"C'è tanta tristezza in quegli occhi..."}]},{"id":"hemma_03","i":3,"title":"L'ospite sgradito","req":"hemma:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"herbalist","t":"Radici viventi acerbe, un ectoplasma spaventoso bello succoso... Poi? Qualcos'altro?"},{"a":"hemma","t":"Va bene così. Troveremo il resto al negozio."},{"a":"herbalist","t":"Grazie, torna a trovarci quando vuoi!"},{"a":"hemma","t":"<c4>... Non dimenticare i foschi artigli.</c4>"},{"a":"hemma","t":"Ah, sì. Un paio di foschi artigli, per favore."},{"a":"herbalist","t":"Chi... COSA ha parlato?"},{"a":"hemma","t":"Nulla di importante. È solo un... ospite, diciamo."},{"a":"hemma","t":"<c4>Fammiuscirefammiuscirefammiuscire.</c4>"},{"a":"hemma","t":"Ugh. Ti calmi, per favore?"},{"a":"hemma","t":"Tieni pure il resto. Arrivederci."},{"a":"herbalist","t":"Grazie per la mancia... e per gli incubi che farò stanotte."}]},{"id":"hemma_a","i":3,"title":"Incontro tra immortali","req":"hemma:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"donovan","t":"Radici viventi acerbe? Scelta interessante."},{"a":"hemma","t":"Perché?"},{"a":"donovan","t":"Le radici viventi sono ingredienti chiave per molte magie legate alla giovinezza e alla longevità."},{"a":"donovan","t":"Sei anche tu un'alchimista? Magari alla ricerca di un modo per nascondere la tua vera età?"},{"a":"hemma","t":"Insinuazioni sull'età di una signora? Che volgarità."},{"a":"hemma","t":"Non siamo alchimisti. Troviamo che i sacrifici di sangue siano molto più efficaci."},{"a":"donovan","t":"Ah, la necromanzia! Un campo di studi spesso frainteso, ma invero rispettabile!"},{"a":"hemma","t":"Per quanto concerne la nostra età... abbiamo smesso di contare gli anni molto tempo fa."},{"a":"donovan","t":"Conosco la sensazione. I decenni sembrano volare dopo qualche secolo!"},{"a":"donovan","t":"Ci si sente soli tra tutte queste efemere, vero?"},{"a":"hemma","t":"Soli non lo siamo mai. Ma ti sconsiglio di curiosare ulteriormente negli affari di una necromante."},{"a":"donovan","t":"Ma certo. Non volevo risultare invadente. Arrivederci!"},{"a":"donovan","t":"Che strana necromante... Possibile che l'abbia già incontrata?"},{"a":"donovan","t":"... Fairlyn?"}]},{"id":"hemma_04","i":4,"title":"Esorcismo","req":"hemma:4","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Tranquilla, Hemma, eccomi! Ho portato Freyja!"},{"a":"priest","t":"Hemma, giusto? Rilassati. Lascia che l'esorcismo faccia il suo corso..."},{"a":"hemma","t":"Non ricordiamo di aver chiesto il vostro aiuto."},{"a":"hemma","t":"<c4>Filate via. Io non vado da nessuna parte.</c4>"},{"a":"lilu","t":"Aaah! Sta prendendo il controllo! Presto, Freyja!"},{"a":"priest","t":"Non... Non riesco! Qualcuno sta bloccando le mie invocazioni!"},{"a":"hemma","t":"Sì, noi. Smettila."},{"a":"priest","t":"Ospiti quello spirito maligno... di tua volontà?"},{"a":"hemma","t":"Ha perso qualche rotella con il tempo, lo ammetto."},{"a":"hemma","t":"<c4>Sono io la vittima, qui! Fammi uscire!</c4>"},{"a":"hemma","t":"Vi assicuro che, più che maligno, è maleducato."},{"a":"hemma","t":"Questa storia non vi riguarda. Ti prego di non immischiarti, Freyja."},{"a":"priest","t":"Questi necromanti... Non fanno che giocare con poteri che non comprendono!"},{"a":"lilu","t":"Non preoccuparti, Freyja! Sono sicura che sa cosa sta facendo."},{"a":"lilu","t":"Giusto?"}]},{"id":"hemma_05","i":5,"title":"Due menti in una","req":"hemma:5","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"hemma","t":"<c4>A quanto pare ci hanno scoperto di nuovo. Pronta a cambiare aria?</c4>"},{"a":"hemma","t":"La colpa è TUA. Se facessi silenzio, sarebbe tutto più semplice."},{"a":"hemma","t":"E comunque no, non ce ne andiamo. Questa città ha molto potenziale."},{"a":"hemma","t":"<c4>Va bene. Allora mi fai uscire, per una volta?</c4>"},{"a":"hemma","t":"Assolutamente no. È già abbastanza difficile tenerti a bada così."},{"a":"hemma","t":"<c4>Fammiuscirefammiuscirefammiuscire.</c4>"},{"a":"hemma","t":"Lo faccio per il tuo bene, Claud."},{"a":"hemma","t":"Ricordalo sempre."}]},{"id":"hemma_06","i":6,"title":"Lascito di menzogne","req":"hemma:6","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Fairlyn!"},{"a":"hemma","t":"Sì?"},{"a":"lilu","t":"Lo sapevo! Hemma è un nome finto! Tu sei il mostro, Fairlyn!"},{"a":"hemma","t":"Oh, cielo. Che subdola ingannatrice abbiamo qui."},{"a":"hemma","t":"È la verità. Ti sei informata bene, a quanto pare."},{"a":"hemma","t":"Forse hai anche sentito parlare di Ariel la folle? O Astrid la disgraziata?"},{"a":"lilu","t":"Ho letto qualcosa... ma sono sparite secoli fa! Non possono essere..."},{"a":"hemma","t":"Tutte noi, ovviamente. Purtroppo siamo perseguitate, e i nomi vanno abbandonati..."},{"a":"lilu","t":"Sei un mostro! Bisogna fermarti!"},{"a":"hemma","t":"E come pensi di farlo? \"Hemma\" è innocente. Chi mai crederebbe a questa tua assurda storia?"},{"a":"hemma","t":"A meno che, ovviamente, tu non abbia intenzione di fermarmi da sola..."},{"a":"lilu","t":"Umpf!"}]},{"id":"hemma_07","i":7,"title":"Unione dell'anima","req":"hemma:7","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"hemma","t":"Sei ancora qui in giro?"},{"a":"lilu","t":"Ti tengo d'occhio. Tu e i tuoi monologhi sospetti..."},{"a":"hemma","t":"Ah, sì. Ti presento Claud, nostro marito. Ha visto giorni migliori."},{"a":"hemma","t":"<c4>Non ne posso più!</c4>"},{"a":"lilu","t":"Cosa gli è successo?"},{"a":"hemma","t":"Un tremendo incidente necromantico. Uno stupido errore l'ha ridotto in punto di morte."},{"a":"hemma","t":"Considerando i nostri peccati sulla Terra, l'aldilà è una prospettiva terrificante per noi necromanti."},{"a":"hemma","t":"Non potendo salvare il suo corpo, abbiamo fatto del nostro meglio... e abbiamo salvato la sua anima."},{"a":"lilu","t":"Una... Unione dell'anima? Questo incantesimo richiede anni di ricerche per preparare un involucro adatto..."},{"a":"hemma","t":"Proprio così. Date le circostanze, abbiamo improvvisato."},{"a":"lilu","t":"Improvvisato? Vuoi dire che... ti sei fusa con l'anima di Claud?"},{"a":"lilu","t":"Un corpo non può sostenere due anime! Provocherebbe..."},{"a":"hemma","t":"Un dolore insopportabile. Follia. Peggio di quanto tu possa immaginare."},{"a":"lilu","t":"Hemma... Perché...? Come...?"},{"a":"hemma","t":"È molto semplice, piccola Lilu. Il fallimento... non è contemplato."}]},{"id":"hemma_08","i":8,"title":"La taglia di un secolo","req":"hemma:8","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Troppo potente per essere esorcizzato... Forse si potrebbe fondere l'anima con qualcos'altro...?"},{"a":"hemma","t":"Sei davvero d'aiuto. Hai sviluppato un interesse per la necromanzia?"},{"a":"lilu","t":"No! Ti odio e odio tutto quello che hai fatto!"},{"a":"lilu","t":"Per come la vedo io, se quel Claud riuscisse a liberarsi, sarebbero guai grossi..."},{"a":"lilu","t":"Ti sto aiutando a sistemare questo disastro, nient'altro!"},{"a":"hemma","t":"Un sentimento nobile. Ma come può una semplice bambina essere d'aiuto?"},{"a":"lilu","t":"Preparare un involucro adatto richiederebbe secoli di ricerche e materiali..."},{"a":"hemma","t":"Non sarà un problema. Guarda."},{"a":"lilu","t":"Come hai fatto a trovare tutta questa roba? Persino i Diamanti neri!"},{"a":"hemma","t":"I secoli trascorsi non sono stati sprecati. Non abbiamo molto tempo."},{"a":"hemma","t":"Ora non resta che trovare un luogo per il rituale. Temiamo che un posto simile non esista."},{"a":"lilu","t":"Già. L'anima deve avere un legame spirituale con la zona, o l'unione fallirà."},{"a":"hemma","t":"<c4>Oppure potreste lasciar libero il vecchio Claud Favius! Si farà un sacco di amici!</c4>"},{"a":"lilu","t":"Aspetta un attimo... hai detto Favius?"}]},{"id":"hemma_09","i":9,"title":"Il castello infestato","req":"hemma:9","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"hemma","t":"Che posto splendidamente infestato."},{"a":"lilu","t":"È un posto orrendo. Nessuna persona sana di mente dovrebbe venirci."},{"a":"lilu","t":"Ma soprattutto, secondo le mie ricerche..."},{"a":"lilu","t":"... Apparteneva a un re folle della famiglia Favius, secoli fa."},{"a":"lilu","t":"Magari Claud è un lontano parente... Speriamo che non abbia avuto nulla a che fare con la rovina del regno."},{"a":"hemma","t":"Lo percepiamo. Abbiamo un legame con questo posto. L'abbiamo trovato."},{"a":"hemma","t":"Siamo in debito con te, Lilu. Ma ora devi lasciarci."},{"a":"lilu","t":"Hemma... Buona fortuna."}]},{"id":"hemma_10","i":10,"title":"Finché morte non ci separi","req":"hemma:10","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"hemma","t":"Un luogo nascosto, buio e infestato, pieno di energia necromantica..."},{"a":"hemma","t":"Per quanto tempo abbiamo cercato un posto simile?"},{"a":"hemma","t":"Ora, per l'involucro adatto..."},{"a":"hemma","t":"Non c'è bisogno di parlare. Sappiamo esattamente ciò che desideri."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"L'armatura del re folle, per sempre legata a questo posto."},{"a":"hemma","t":"<c1>Unione dell'anima!</c1>"},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Ugh... Sentiamo... o io...?"},{"a":"hemma","t":"Avevo dimenticato questa sensazione di solitudine..."},{"a":"hemma","t":"Ho sofferto un'eternità per salvarti, caro, perché so che avresti fatto lo stesso per me."},{"a":"hemma","t":"Arriveranno avventurieri coraggiosi. Combatti contro di loro e guarisci la tua esistenza tormentata attraverso il massacro."},{"a":"Castle_Boss","t":"..."},{"a":"hemma","t":"Addio, mio amato. Ma solo la morte ci separerà davvero."}]},{"id":"hemma_epilogue","i":11,"title":"Epilogo","req":"hemma:11","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"Castle_Boss","t":"<c4>STOLTI!!! OSATE CAMMINARE SULLE MIE TERRE?</c4>"},{"a":"sia","t":"Che nemico seccante!"},{"a":"Castle_Boss","t":"<c4>MWAHAHAHA! DEBOLI MORTALI!</c4>"},{"a":"argon","t":"Lady Sia! Rudo! Dobbiamo ritirarci!"},{"a":"rudo","t":"Giammai! Non gli concederò un solo centimetro!"},{"a":"yami","t":"Ho trovato un'uscita. Sbrighiamoci!"},{"a":"rudo","t":"Bah! Tornerò, stupido ammasso di latta! Mi hai sentito?"},{"a":"Castle_Boss","t":"<c4>TORNA QUANDO SEI IN GRADO DI AFFRONTARMI!</c4>"},{"a":"Castle_Boss","t":"<c4>DI' AI TUOI PIÙ VALOROSI EROI CHE IL RE TIRANNO LI ATTENDE!</c4>"}]}]},{"id":"lilu","name":"Lilu","chapters":[{"id":"lilu_01","i":1,"title":"Apprendista precoce","req":"lilu:1","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Beh, Pollux? Che ne pensi di questo nuovo incantesimo? Perfetto, vero?"},{"a":"lilu","t":"Già, questa volta non possiamo proprio sbagliare!"},{"a":"herbalist","t":"Buongiorno, Lilu. Sei qui per la consegna settimanale di radici viventi?"},{"a":"lilu","t":"Sì, grazie Maribel!"},{"a":"herbalist","t":"Certo che ne hai ordinate un sacco, questa settimana! Che ci deve fare il tuo maestro con tutte queste?"},{"a":"lilu","t":"A dire la verità, circa la metà sono per me. Sto conducendo degli studi importanti!"},{"a":"herbalist","t":"Oh? E di che tipo?"},{"a":"lilu","t":"Incantesimi curativi! Ho trascorso tutta la settimana scorsa a curare tagli e lividi nella sala di addestramento!"},{"a":"herbalist","t":"D'accordo. Sono sicura che gli eroi sono molto felici di averti con loro."},{"a":"herbalist","t":"...E anche Argon!"},{"a":"lilu","t":"...!"},{"a":"lilu","t":"Io... devo andare! Grazie!"}]},{"id":"lilu_02","i":2,"title":"Fosche notizie","req":"lilu:2","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Ecco qua, mastro Grimar. Le radici viventi di questa settimana."},{"a":"wizard","t":"Grazie, Lola. Ecco qui i tuoi compiti per oggi."},{"a":"lilu","t":"Oh! Un tomo magico! Parla di guarigione?!"},{"a":"lilu","t":"\"Manuale di maledizioni del miscredente\"...?"},{"a":"lilu","t":"Questo libro è troppo avanzato! Ha perfino un'intera sezione dedicata alle fatture!"},{"a":"wizard","t":"...Fatture?"},{"a":"wizard","t":"Mmm... fatture...?"},{"a":"lilu","t":"Maestro?"},{"a":"wizard","t":"35 anni fa, in questo preciso giorno... io...!"},{"a":"lilu","t":"Mastro Grimar!?"},{"a":"wizard","t":"...Ho dimenticato. E tu chi sei?"},{"a":"lilu","t":"...Sono Lilu, la sua apprendista. O Lola, a volte..."},{"a":"lilu","t":"Oh beh, non fa niente. Studierò questo libro. Grazie, Grim."}]},{"id":"lilu_03","i":3,"title":"Una mente confusa","req":"lilu:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Aggiungere un pizzico di Polvere d'argento e... fatto!"},{"a":"lilu","t":"Guarda come brilla! Non male, eh Pollux?"},{"a":"lilu","t":"Se il Manuale di maledizioni del miscredente è corretto, questa pozione dovrebbe..."},{"a":"wizard","t":"Lola, cos'è questa confusione? Sto cercando di dormire!"},{"a":"lilu","t":"Mastro Grimar! Grazie al suo libro, ho preparato una pozione molto avanzata! Dovrebbe..."},{"a":"wizard","t":"Cos'hai fatto?!"},{"a":"wizard","t":"Bene allora, dai qua! Assaggiamo!"},{"a":"wizard","t":"..."},{"a":"lilu","t":"Mastro Grimar?"},{"a":"wizard","t":"Lilu! Io d-d-devo e-e-essere li-liberato! Fa-fammi uscire da questa s-stupida m-mente imbecille!"},{"a":"lilu","t":"M-mastro Grimar! Si sente bene?"},{"a":"wizard","t":"..."},{"a":"wizard","t":"*Burp* Un po' fruttato!"},{"a":"wizard","t":"Non male, Lola. Ora, torna ai tuoi compiti."},{"a":"lilu","t":"È stato davvero bizzarro."}]},{"id":"lilu_a","i":3,"title":"Passione per le collezioni","req":"lilu:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"lilu","t":"Grimar, non sapevo avessi un secondo <c1>Libro delle collezioni</c1>!"},{"a":"wizard","t":"<c1>Libro delle collezioni</c1>? Suona familiare..."},{"a":"lilu","t":"Wow! Questo è pieno di informazioni! <c1>Damocle</c1>... La <c1>Cittadella d'ambra</c1>..."},{"a":"lilu","t":"La <c1>grande bacchetta di Grimar</c1>... Glielo hai dato tu il nome a questa?"},{"a":"lilu","t":"Ci sono un sacco di pagine! Dovevi essere un collezionista incredibile!"},{"a":"sundragon","t":"Puoi dirlo forte!"},{"a":"wizard","t":"Sondra, vecchio mio, sei tu?"},{"a":"lilu","t":"Wow! Vi conoscete?"},{"a":"sundragon","t":"Proprio così. Da giovane, Grimar era ossessionato dal suo Libro delle collezioni."},{"a":"sundragon","t":"Ricordo che gli aveva fatto meritare un titolo prestigioso tra i suoi colleghi umani... \"Nerd\", giusto?"},{"a":"lilu","t":"Ehm..."},{"a":"sundragon","t":"Ci siamo incontrati durante la sua ricerca di oggetti rari e abbiamo creato assieme il <c1>calderone della fusione</c1>."},{"a":"sundragon","t":"Passava giorno e notte a fondere centinaia di oggetti, mettendoci ancora più foga nelle notti di luna piena!"},{"a":"lilu","t":"E nonostante tutti questi sforzi... la sua collezione è ancora incompleta!"},{"a":"lilu","t":"Giuro che ti curerò, mastro Grimar! Così potrai completare la missione della tua vita!"},{"a":"sundragon","t":"Il tempo non è clemente con gli esseri umani. Ti auguro buona fortuna, piccolina."}]},{"id":"lilu_04","i":4,"title":"La fine della stirpe","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"C'è qualcosa che non va con mastro Grimar..."},{"a":"lilu","t":"La sua voce... era come se qualcuno parlasse da dentro di lui!"},{"a":"lilu","t":"Forse abbiamo davanti un complesso incantesimo di trasmutazione?"},{"a":"lilu","t":"O forse addirittura..."},{"a":"leather","t":"Ehi, Lilu! Qualcosa è andato storto al banchetto del re!"},{"a":"lilu","t":"Tamas? Che succede?"},{"a":"leather","t":"Si parla di un invasore al castello. Da paura!"},{"a":"lilu","t":"Un invasore...! Oh no, oggi è il primo giorno di Argon come cavaliere!"},{"a":"lilu","t":"Grazie Tamas, devo andare!"},{"a":"lilu","t":"Oh no! Che sta succedendo qui!?"},{"a":"lilu","t":"Argon, dove sei!?"},{"a":"king","t":"Aaargh..."},{"a":"lilu","t":"RE REINHOLD!? Tutto bene!?"},{"a":"king","t":"Aahh... la mia preziosa vita... effimera..."},{"a":"lilu","t":"Santo cielo...!"},{"a":"lilu","t":"Concentrati, Lilu! Ricordati dell'addestramento del Saggio!"},{"a":"lilu","t":"Re Reinhold! Resista! <c1>Guarigione</c1>!"},{"a":"king","t":"Non serve a niente... ti prego... conservate il mio meraviglioso cadavere..."},{"a":"lilu","t":"Non sortisce effetti..."},{"a":"lilu","t":"Oh no! Che si tratti di... veleno?"},{"a":"lilu","t":"Proprio come i miei genitori! Ma questa volta non fallirò! Non posso!"},{"a":"lilu","t":"<c1>Grande purificazione antiveleno!</c1>"},{"a":"king","t":"Aaah... Huh?"},{"a":"lilu","t":"Re Reinhold! Come sta?"},{"a":"lilu","t":"Un momento... Questa tazza l'ha protetta dallo shuriken! Non è stato minimamente ferito!"},{"a":"king","t":"Oh! Davvero? Forse ho un pochino esagerato."},{"a":"king","t":"Dopotutto, la morte di un monarca è una faccenda drammatica."},{"a":"lilu","t":"Argh! Reinhold!"}]},{"id":"lilu_05","i":5,"title":"Scegli il tuo veleno","req":"lilu:5","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Ugh. C'è mancato poco... per così dire."},{"a":"lilu","t":"Se Reinhold fosse stato davvero avvelenato, non credo che sarei riuscita a salvarlo."},{"a":"lilu","t":"Devo impegnarmi di più. Non voglio che ad altri succeda quello che è successo a me..."},{"a":"lilu","t":"Signorina Sia!"},{"a":"sia","t":"Ah, la star del momento! Puoi stare tranquilla: un cavaliere è stato mandato sulle tracce dell'invasore."},{"a":"lilu","t":"(Un cavaliere? Buona fortuna, Argon!)"},{"a":"sia","t":"Grazie per aver salvato il nostro re, nonostante le circostanze."},{"a":"lilu","t":"Di nulla! Ma se dovesse succedere di nuovo, temo che non potrei fare granché..."},{"a":"lilu","t":"Signorina Sia, lei è pratica di veleni?"},{"a":"sia","t":"Ma certamente. L'aconito, noto anche come Strozzalupo, è un veleno efficacissimo."},{"a":"sia","t":"Ma personalmente preferisco la ricina: silenziosa, letale e facilmente reperibile..."},{"a":"lilu","t":"Ehm... In realtà io pensavo piuttosto a come contrastarli."},{"a":"sia","t":"Oh. È un aspetto che non ho mai considerato, sinceramente."},{"a":"lilu","t":"Come non detto, allora."}]},{"id":"lilu_06","i":6,"title":"Maestro e allieva","req":"lilu:6","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Mastro Grimar, sono tornata!"},{"a":"wizard","t":"Ah Lola, bentornata."},{"a":"lilu","t":"È successa una cosa incredibile! Hanno tentato di assassinare il re!"},{"a":"wizard","t":"Ah sì?"},{"a":"lilu","t":"Un'assassina è sbucata fuori dal nulla e l'ha attaccato con uno shuriken!"},{"a":"lilu","t":"A quel punto, io sono corsa ad aiutarlo, mentre lui era disteso a terra, agonizzante...!"},{"a":"wizard","t":"Ehm... Come hai detto di chiamarti?"},{"a":"lilu","t":"Oh, giusto. Dimenticavo la sua condizione... Devo rimettermi al lavoro!"},{"a":"lilu","t":"La causa potrebbe anche essere un veleno..."},{"a":"lilu","t":"Vediamo... Grimar è molto vecchio..."},{"a":"lilu","t":"Cosa ne pensi, Pollux?"},{"a":"lilu","t":"Sì, faremo qualche indagine in città."},{"a":"lilu","t":"Forse qualcuno dei residenti più anziani ricorderà come si comportava Grimar da giovane..."}]},{"id":"lilu_07","i":7,"title":"Conoscenza ancestrale","req":"lilu:7","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Mastro Theodore!"},{"a":"master","t":"Oh, Lilu! In cosa posso esserti d'aiuto?"},{"a":"lilu","t":"Mi chiedevo se potevi raccontarmi un po' com'era Grimar da giovane..."},{"a":"lilu","t":"Visto che tu sei... uh... vecchio."},{"a":"master","t":"Oh oh oh! Certamente, certamente."},{"a":"master","t":"Il buon vecchio Grimar è sempre stato un po'... eccentrico, diciamo."},{"a":"master","t":"Ma quando io ero solo un giovanotto, la sua mente era molto più lucida. Era un mio degno rivale agli scacchi!"},{"a":"master","t":"Ora che ci penso, ha iniziato a essere un po' strano dopo essere tornato da quel viaggio alle Rovine di Chronos."},{"a":"lilu","t":"Le Rovine di Chronos! È un posto pericolosissimo!"},{"a":"lilu","t":"Un'intera civiltà ridotta in rovine mentre studiava la manipolazione magica del tempo..."},{"a":"lilu","t":"Quel luogo è ricolmo di anomalie magiche! Che interesse aveva Grimar a visitarlo?"},{"a":"lilu","t":"Hai ragione, Pollux. È l'unico indizio che abbiamo, dobbiamo andare a investigare."},{"a":"lilu","t":"Ma ci servirà qualcuno che ci faccia da scorta... Potremmo chiedere ad Argon?"},{"a":"lilu","t":"No! E se un vortice temporale lo fa improvvisamente diventare un vecchio? O magari come Grimar..."},{"a":"lilu","t":"Mi viene in mente solo un'altra persona che potrebbe aiutarci..."},{"a":"lilu","t":"Non sarà facile, Pollux, ma dobbiamo provarci!"},{"a":"lilu","t":"Grazie mille, Theodore! Il tuo aiuto è stato prezioso!"},{"a":"master","t":"Figurati, Lilu! A presto!"},{"a":"master","t":"..."},{"a":"master","t":"Quel gufo è davvero intelligente..."}]},{"id":"lilu_08","i":8,"title":"Causa comune","req":"lilu:8","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Rudo, per favore! Non andartene, devo parlarti!"},{"a":"rudo","t":"Sparisci, mocciosa. Non mi interessa."},{"a":"rudo","t":"Vai a giocare con il tuo gufo da un'altra parte!"},{"a":"lilu","t":"So che non ti piacciono gli incantatori... ma ho davvero bisogno del tuo aiuto!"},{"a":"lilu","t":"Devo avventurarmi nelle Rovine di Chronos e non posso farlo da sola! "},{"a":"rudo","t":"Perché non chiedi a quell'Argon? Non è il tuo prode cavaliere?"},{"a":"lilu","t":"Argon è... Uh, ha altro da fare al momento..."},{"a":"lilu","t":"Dunque è inutile che io insista..."},{"a":"rudo","t":"Vedo che hai capito, mocciosa."},{"a":"tavern","t":"Un vero peccato, tesoro."},{"a":"tavern","t":"Pare che nessuno abbia mai sconfitto il Signore dei ciclopi delle Rovine di Chronos in singolar tenzone..."},{"a":"tavern","t":"Ci vorrebbe davvero un guerriero senza pari per scortare Lilu in quelle rovine!"},{"a":"rudo","t":"... Mai sconfitto, dici?"},{"a":"rudo","t":"E va bene, ci sto. Quanta roba potrò distruggere?"},{"a":"lilu","t":"Sicuramente un sacco!"},{"a":"lilu","t":"Vedi, devo trovare la fonte del flusso temporale che proviene dai cristalli e isolare..."},{"a":"rudo","t":"Vai alla parte della distruzione."},{"a":"lilu","t":"... Ci sono mostri e cristalli magici da distruggere."},{"a":"rudo","t":"Affare fatto. Mi sei debitrice, mocciosa."},{"a":"lilu","t":"Fantastico! Grazie infinite, Rudo!"},{"a":"rudo","t":"Ringraziami al nostro ritorno, mocciosa. Non sarà una passeggiata."},{"a":"lilu","t":"Ti curerò tutte le ferite se i mostri dovessero rivelarsi troppo pericolosi!"},{"a":"rudo","t":"Umpf. Non penso accadrà."},{"a":"lilu","t":"Grazie anche a te, Naya!"},{"a":"tavern","t":"Nessun problema, tesoro."}]},{"id":"lilu_09","i":9,"title":"Mondo specchio","req":"lilu:9","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"rudo","t":"Terrò a bada il ciclope! Proseguite!"},{"a":"rudo","t":"Avanti, ciccione! Vieni a fare la pappa!"},{"a":"lilu","t":"D'accordo! Buona fortuna!"},{"a":"lilu","t":"Questa è... la Stanza del tempo. E in base alle mie ricerche..."},{"a":"lilu","t":"Questo pozzo dovrebbe essere connesso a una linea temporale frammentata!"},{"a":"lilu","t":"Un universo parallelo dove la città di Chronos prospera ancora..."},{"a":"lilu","t":"Guarda, Pollux! In fondo all'acqua... si intravede qualcosa!"},{"a":"lilu","t":"Sembra che laggiù gli abitanti di Chronos trascorrano una vita normale..."},{"a":"lilu","t":"Ehi... Sbaglio o quel tipo ci sta salutando?"},{"a":"lilu","t":"Somiglia molto a... Grimar!?"}]},{"id":"lilu_10a","i":10,"title":"La maledizione degli anni","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Grimar!!! Bevi questo!"},{"a":"wizard","t":"Uh? Ha qualcosa di... familiare."},{"a":"lilu","t":"È un infuso speciale preparato con acqua di Chronos..."},{"a":"wizard","t":"Stabilizzato e trattato due volte con filo del fato...?"},{"a":"lilu","t":"... e reso in forma materiale con dell'ectoplasma distillato."},{"a":"wizard","t":"E un pizzico di corallo profondo per l'aroma!"},{"a":"wizard","t":"Eccellente, Lilu. Riempi d'orgoglio il tuo maestro."},{"a":"lilu","t":"G-Grimar... Sei di nuovo normale! Ha funzionato!"},{"a":"wizard","t":"Che esperienza peculiare... È come se la nebbia si fosse sollevata dalla mia mente..."},{"a":"lilu","t":"Ho una vaga idea di come funzioni la pozione, ma... c'è qualcosa che non ha molto senso."},{"a":"lilu","t":"Ti abbiamo visto nell'acqua! Nella linea temporale frammentata!"},{"a":"wizard","t":"Oh, davvero? Ho una teoria in merito..."},{"a":"wizard","t":"Pollux, tesoro, andresti a chiamare il vecchio Owen? Credo ci sia molto da spiegare..."}]},{"id":"lilu_10b","i":11,"title":"Teorema temporale","req":"lilu:10","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"elderowen","t":"Perbacco, vecchio mio! Che storia incredibile!"},{"a":"lilu","t":"Mi sembra impossibile da credere... Grimar è un superstite della città di Chronos?"},{"a":"wizard","t":"Quando l'incantesimo temporale è impazzito, l'intera città è stata spedita in un'altra linea temporale."},{"a":"elderowen","t":"Ricordo quel giorno come se fosse ieri. Un'intera città svanita in un lampo!"},{"a":"elderowen","t":"Nelle rovine non trovammo che un unico bambino disperso..."},{"a":"lilu","t":"Era Grimar, giusto? È difficile immaginarvi come due bambini..."},{"a":"elderowen","t":"Oh oh! Abbiamo fatto subito amicizia, vero?"},{"a":"wizard","t":"Vero. Iniziai a studiare per diventare stregone e investigare quel misterioso incidente io stesso."},{"a":"wizard","t":"Se ciò che ha visto Lilu è vero, credo che esista un altro Grimar."},{"a":"lilu","t":"L'altro Grimar che abbiamo visto... Allora esisti anche nell'altra linea temporale?"},{"a":"wizard","t":"Così sembrerebbe. All'inizio ciò non aveva conseguenze, ma..."},{"a":"wizard","t":"Man mano che entrambi i Grimar crescevano, le nostre esperienze e personalità erano sempre più diverse."},{"a":"lilu","t":"E il crescere di tale paradosso magico ha iniziato a pesare sulla tua mente..."},{"a":"lilu","t":"Ho capito! Bere la pozione delle Rovine di Chronos deve averti ricollegato all'altra linea temporale!"},{"a":"wizard","t":"Sì, è questa la mia teoria, e credo che anche l'altro Grimar lo abbia compreso."},{"a":"lilu","t":"Wow... è davvero incredibile. Mi sa che è meglio dormirci su... Vieni, Pollux?"},{"a":"elderowen","t":"Io e te, invece, ne abbiamo di cose da raccontarci, vero, vecchio Grim?"},{"a":"wizard","t":"Parla per te, bacucco! Non mi sono mai sentito così giovane!"}]},{"id":"lilu_epilogue","i":12,"title":"Epilogo","req":"lilu:11","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Ciao Grimar! Ecco una nuova ricetta, dovrebbe durare più a lungo!"},{"a":"wizard","t":"Un miglioramento notevole! I tuoi genitori sarebbero orgogliosi di te."},{"a":"lilu","t":"Se solo avessi iniziato prima a studiare l'alchimia..."},{"a":"wizard","t":"So come ti senti. Se avessi avuto il pieno controllo di me, forse..."},{"a":"lilu","t":"Non preoccuparti. Ho deciso di concentrarmi sul futuro. Migliorerò ed eviterò ad altri questo destino."},{"a":"lilu","t":"Sono certa che i miei genitori avrebbero voluto così."},{"a":"wizard","t":"Sei cresciuta tantissimo... Ti riconosco a stento."},{"a":"wizard","t":"Ora che ci penso... Come hai detto di chiamarti?"},{"a":"lilu","t":"Oh no! Gli effetti stanno già svanendo! Devo subito..."},{"a":"wizard","t":"Oh oh oh! Scherzavo. Stavolta andrà bene, me lo sento."},{"a":"wizard","t":"Ora che mi sento bene, perché non studiamo un po' di magia?"},{"a":"wizard","t":"Il maestro ha ancora tanti trucchi da insegnare!"},{"a":"lilu","t":"Oh! Magari la polimorfosi? Non vedo l'ora!"}]}]},{"id":"malady","name":"Malady","chapters":[{"id":"malady_01","i":1,"title":"Scolpito nella pietra","req":"malady:1","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"Missione compiuta! Bambini smarriti: ritrovati e salvati!"},{"a":"argon","t":"Le Rovine di Chronos non sono un posto sicuro in cui giocare."},{"a":"argon","t":"Meglio che mi dia una mossa anch'io!"},{"a":"malady","t":"Spero che quei malvagi goblinelli mi lascino in pace oggi."},{"a":"argon","t":"Ehi, signorina! Ti sei persa anche tu?"},{"a":"malady","t":"Non... non avvicinarti!"},{"a":"argon","t":"Uh?"},{"a":"argon_stone","t":"..."},{"a":"malady","t":"Guardarmi negli occhi ti trasformerà per sempre in pietra. Questa è la maledizione di Medusa."},{"a":"malady","t":"Anche se... mi sembravi simpatico."},{"a":"malady","t":"... Mi dispiace."}]},{"id":"malady_02","i":2,"title":"Il Marmoreo","req":"malady:2","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"*Gnnnh*... Owen... l'anziano..."},{"a":"elderowen","t":"Lilu! Perché mai stai trascinando in giro quella statua?"},{"a":"elderowen","t":"Una statua di... Argon?"},{"a":"lilu","t":"Uff... Pant... Questa statua È Argon!"},{"a":"elderowen","t":"Oh, cielo. È stato pietrificato, vero?"},{"a":"lilu","t":"Penso di sì. L'ho trovato così nelle Rovine di Chronos."},{"a":"lilu","t":"Fortunatamente, Rudo mi ha aiutato a trasportarlo per un po'!"},{"a":"elderowen","t":"Che bel guaio. Riesci a curarlo?"},{"a":"lilu","t":"Probabilmente sì! Ma gli ingredienti sono rari, non sarà facile."},{"a":"lilu","t":"Radunerò abitanti della città e negoziante! Lascio Argon alle tue cure!"},{"a":"elderowen","t":"Certo. Spero non ti dispiaccia passare un po' di tempo come decorazione da giardino, ragazzo mio."},{"a":"argon_stone","t":"..."},{"a":"elderowen","t":"Sciò, maledetti piccioni! Via!"}]},{"id":"malady_03","i":3,"title":"Occhio per occhio","req":"malady:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"... Questo rampicante incolto dovrebbe essere abbastanza vecchio da poter essere utilizzato. Non ne sono rimasti molti..."},{"a":"lilu","t":"Il prossimo è... sangue di Medusa. Non sarà facile."},{"a":"malady","t":"Uhm..."},{"a":"lilu","t":"AAAH! Mostro!"},{"a":"malady","t":"... Sei un'amica dell'umano di prima?"},{"a":"lilu","t":"Argon? Aspetta, sei stata TU a ridurlo così?"},{"a":"lilu","t":"Beh, questo rende le cose MOLTO più semplici. Si dà il caso che io abbia bisogno di sangue di Medusa..."},{"a":"malady","t":"No, ti prego! Non volevo fargli del male."},{"a":"lilu","t":"Certo, come no! L'hai trasformato in pietra!"},{"a":"malady","t":"... Mi dispiace. Avevo paura e i nostri sguardi si sono incrociati."},{"a":"malady","t":"Non sapevo come reagire... Nessuno era mai stato gentile con me prima."},{"a":"lilu","t":"... Cavolo, non dev'essere stato facile."},{"a":"malady","t":"Se hai bisogno di sangue... te lo darò."},{"a":"malady","t":"In cambio, ti prego... portami con te. Vorrei chiedergli scusa."},{"a":"lilu","t":"... Va bene. L'idea non mi piace, ma se io fossi stata trasformata in pietra, non credo che Donovan sarebbe stato qui a salvarci."},{"a":"lilu","t":"Ti terrò d'occhio. Tu, al contrario, tienimeli lontani di dosso!"},{"a":"malady","t":"... Sì! Grazie."}]},{"id":"malady_04","i":4,"title":"Dalla pietra alla carne... e ritorno","req":"malady:4","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Fatto! Questa pozione dovrebbe funzionare. Splash splash!"},{"a":"argon","t":"... Aaah! Che bello potersi stiracchiare!"},{"a":"argon","t":"Un momento, che è successo?"},{"a":"lilu","t":"La qui presente Malady ti ha trasformato in pietra per sbaglio e voleva scusarsi."},{"a":"malady","t":"C-ciao. Scusa, non volevo..."},{"a":"argon","t":"Beh, mi sembra di essere tutto intero! Anzi, mi sento benissimo... forse solo un po' indolenzito."},{"a":"argon","t":"Sei Malady? Io sono Argon, piacere di conoscerti!"},{"a":"argon","t":"Ehi, ti è scivolata la bandana. Te la sistemo io!"},{"a":"lilu","t":"Argon! No!"},{"a":"argon_stone","t":"..."},{"a":"lilu","t":"Argon... Dovrò insegnargli qualcosa sulle Meduse..."},{"a":"malady","t":"Oh no! Mi dispiace tanto!"},{"a":"lilu","t":"Non preoccuparti. Se l'è cercata, stavolta."},{"a":"malady","t":"Sono pronta per un altro prelievo di sangue..."},{"a":"lilu","t":"Non conosco bene la fisiologia delle Meduse, ma dovresti aspettare qualche giorno tra un prelievo e l'altro."},{"a":"lilu","t":"Resta qui nel frattempo. Non è sicuro andare in giro da sola se sei debole."},{"a":"lilu","t":"Anche se, considerando i tuoi... poteri, forse è meglio chiedere prima a Owen l'anziano..."},{"a":"malady","t":"... Sì."}]},{"id":"malady_05","i":5,"title":"Benvenuta a casa","req":"malady:5","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Owen l'anziano, siamo tornati!"},{"a":"elderowen","t":"Argon è guarito? Ottima notizia!"},{"a":"lilu","t":"Non proprio. Ma..."},{"a":"malady","t":"..."},{"a":"elderowen","t":"Per la dea! Una Medusa, qui!?"},{"a":"lilu","t":"Lei è Malady. Mi ha aiutato a curare Argon!"},{"a":"lilu","t":"Dovrà restare qui per qualche giorno, così potremo curarlo... di nuovo."},{"a":"elderowen","t":"Capisco. Non percepisco cattive intenzioni da parte tua. Perdonami per la mia reazione, Malady."},{"a":"malady","t":"A causa della mia maledizione... sono odiata da tutti, persino dagli altri mostri. Ci sono abituata."},{"a":"elderowen","t":"Le porte della città sono sempre aperte a chi desidera lavorare per il bene di tutti."},{"a":"malady","t":"... Davvero?"},{"a":"elderowen","t":"Finché tieni gli occhi coperti, non c'è alcun pericolo."},{"a":"elderowen","t":"Malady... Ti auguro più fortuna qui che tra i tuoi simili."},{"a":"malady","t":"Grazie... Non sono mai stata la benvenuta da nessuna parte prima d'ora..."},{"a":"elderowen","t":"Dovresti andare presto dal negoziante. Lì c'è sempre lavoro per i giovani come te."},{"a":"lilu","t":"Potresti venire in missione con noi!"},{"a":"malady","t":"Lo farò! Grazie, Lilu e Owen."}]}]},{"id":"polonia","name":"Polonia","chapters":[{"id":"polonia_01","i":1,"title":"Marinaio d'acqua dolce supremo","req":"polonia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho! Marinai d'acqua dolce!"},{"a":"polonia","t":"Avete mai sognato di vivere avventure spericolate di cappa e spada in salsa piratesca sui sette mari?"},{"a":"polonia","t":"Io, Capitan Polonia Del Monte, sto reclutando gentaglia per la ciurma della mia nave!"},{"a":"polonia","t":"In quanto nipote del leggendario pirata Baross Del Monte, non posso che promettervi avventure e bottini a non finire!"},{"a":"argon","t":"Capitan Polonia, giusto?"},{"a":"polonia","t":"Proprio così. Ti interessa l'offerta? Un baldo giovane come te sarebbe il benvenuto."},{"a":"argon","t":"B-Baldo giovane!?"},{"a":"argon","t":"Ehm, non proprio! Io sono Argon, cavaliere in addestramento!"},{"a":"argon","t":"La pirateria è illegale, perciò... per favore, si arrenda e mi segua senza tante storie!"},{"a":"polonia","t":"Corpo di mille balene! Un maledetto cavaliere..."},{"a":"polonia","t":"Err, vedi... la mia condizione di pirata è... legale. Un po' come quel... Robin Hood."},{"a":"polonia","t":"Rubo ai ricchi per dare ai poveri."},{"a":"argon","t":"Oh! Mi sembra proprio una cosa buona e giusta. E va bene, vada pure."},{"a":"polonia","t":"Fiù."},{"a":"tavern","t":"Niente fortuna nemmeno oggi, eh?"},{"a":"polonia","t":"Ahrrr, la vita in alto mare sa essere spietata."}]},{"id":"polonia_02","i":2,"title":"La leggenda di Del Monte","req":"polonia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"tavern","t":"Niente più reclutamento oggi, Polonia?"},{"a":"polonia","t":"È tutto inutile. Come capitano pirata sono un fallimento... Non sono nemmeno degna di portare il nome dei Del Monte."},{"a":"tavern","t":"Questo Baross Del Monte... era tuo nonno, vero?"},{"a":"polonia","t":"È così! Una leggenda tra le leggende! I tempi moderni non hanno molta misericordia di noi pirati..."},{"a":"polonia","t":"Al giorno d'oggi, tutte le navi mercantili sono equipaggiate con elaborati strumenti di rilevazione magica per evitare facilmente noi lupi di mare."},{"a":"polonia","t":"Tutti tranne uno! Magia o no, Baross non veniva mai scoperto finché non era troppo tardi, quando colpiva col favore della nebbia!"},{"a":"polonia","t":"Li derubava di tutti i preziosi, lasciandosi dietro soltanto l'eco delle sue sghignazzate come biglietto da visita..."},{"a":"polonia","t":"Persino dopo che tutti gli altri pirati avevano ormai appeso la benda al chiodo, Baross continuò per decenni a essere il terrore dei mari!"},{"a":"tavern","t":"È un'eredità piuttosto impegnativa da portare sulle spalle!"},{"a":"polonia","t":"Già! E dopo ogni viaggio, Baross trovava sempre il tempo per visitare la sua nipotina e raccontarle le sue ultime avventure..."},{"a":"polonia","t":"Issate la bandiera nera! Fuoco ai cannoni! Tutti gli uomini a dritta, prepararsi all'arrembaggio!"},{"a":"tavern","t":"Dritta? Non si dice tribordo?"},{"a":"polonia","t":"Argh! Sono solo una marinaia da quattro soldi con un costume elaborato che cerca a tutti i costi di parlare come un pirata."},{"a":"polonia","t":"E poi, cos'è un pirata senza una nave?"},{"a":"tavern","t":"Niente nave, eh? Forse dovresti cominciare da lì."},{"a":"polonia","t":"Uh?"},{"a":"tavern","t":"Un capitano senza un'imbarcazione non riuscirà di certo a radunare una ciurma in tempi brevi."},{"a":"tavern","t":"Ma se una nave è quel che ti serve, credo di conoscere la persona che fa al caso tuo."},{"a":"polonia","t":"Davvero?"},{"a":"polonia","t":"Voglio dire... Per mille teschi rinsecchiti, grazie, signora della taverna! Capitan Polonia è in debito con te!"},{"a":"tavern","t":"Oh, ci conto, credimi!"}]},{"id":"polonia_03","i":3,"title":"Carpentiere navale fatto e finito","req":"polonia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"carpenter","t":"Vuoi che ti costruisca una nave intera?"},{"a":"polonia","t":"Proprio così. Sei in grado di farlo?"},{"a":"carpenter","t":"Ci puoi scommettere! Sarà il mio capolavoro. Mostrami quei progetti."},{"a":"carpenter","t":"Mmh... sono piuttosto dettagliati. Cosa sono questi scarabocchi?"},{"a":"polonia","t":"La mia calligrafia. Non so leggere."},{"a":"carpenter","t":"Ah, beh, questo spiega un po' di cose. In ogni caso, sono più che sufficienti."},{"a":"polonia","t":"Yo ho ho! Sarà la più grande nave a solcare i sette mari dai tempi di Baross e della Bonaventura!"},{"a":"carpenter","t":"Tuttavia, resta da chiarire la questione dei fondi. Sei sicura che puoi permetterti un lavoro del genere?"},{"a":"polonia","t":"Certo, i dobloni non saranno un problema. Costruisci la nave, io procurerò il bottino."}]},{"id":"polonia_a","i":3,"title":"In gamba","req":"polonia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"polonia","t":"Ehilà, carina. Tu sei una guaritrice, non è così?"},{"a":"priest","t":"Ah, sì. Io sono Freyja, sacerdotessa di questo tem..."},{"a":"polonia","t":"Mozzami la gamba."},{"a":"priest","t":"Come, scusa?"},{"a":"polonia","t":"Ti ho chiesto di mozzarmi la gamba!"},{"a":"priest","t":"Santo cielo, no! Perché mai vorresti una cosa del genere?"},{"a":"polonia","t":"Per essere un pirata! Che razza di capitano sarei senza la mia gamba di legno?"},{"a":"polonia","t":"Tu pensa solo a mozzarmi la gamba e a ricucirla con la tua bella magia!"},{"a":"priest","t":"Assolutamente no. Ho prestato giuramento alla Dea di non arrecare danno a nessun essere umano."},{"a":"polonia","t":"Argh, inutili topi di sentina! E va bene! Ma da me non vedrai nessun doblone!"},{"a":"priest","t":"Che strana ragazza..."}]},{"id":"polonia_04","i":4,"title":"La quota del capitano","req":"polonia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"polonia","t":"Ahrrr, questi yeti sono carichi di bottino! Finanzierò la costruzione della mia nave in un battibaleno."},{"a":"leather","t":"Bene sorella, sono qui. Allora, cosa devo fare?"},{"a":"polonia","t":"Per te sono Capitan Polonia, mozzo."},{"a":"leather","t":"Come vuoi, capitan sorella. Qual è il mio compito?"},{"a":"polonia","t":"Hai portato il tuo carrello. Trasporta il bottino mentre io alleggerisco questi yeti dal primo all'ultimo."},{"a":"leather","t":"Accidenti, capitan sorella... Stai derubando quelle creature gentili e pelose?"},{"a":"polonia","t":"Certo. Per qualche strana ragione, hanno con sé oggetti preziosi a vagonate, come martelli da guerra e archi compositi."},{"a":"leather","t":"Che mi dici delle pelli, capitan sorella? Posso averle io?"},{"a":"polonia","t":"Resta al tuo posto, mozzo! I pirati saccheggiano, non uccidono!"},{"a":"leather","t":"Oh, che spreco."},{"a":"polonia","t":"Affatto. Se lasci le tue vittime in vita, poi raccoglieranno altro bottino e potrai svaligiarle di nuovo più avanti. È l'ABC dell'economia."},{"a":"polonia","t":"E ora vedi di tenere il passo se vuoi la tua parte, mozzo!"},{"a":"leather","t":"Agli ordini, capitan sorella."}]},{"id":"polonia_05","i":5,"title":"Il viaggio inaugurale","req":"polonia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"carpenter","t":"Ammira il lavoro e capolavoro di una vita!"},{"a":"polonia","t":"Hai fatto scendere una lacrimuccia a quest'arida lupa di mare. È... è meravigliosa."},{"a":"carpenter","t":"Lo è davvero, eh? Ho dovuto fare qualche taglio, specialmente per la tua insistente richiesta di avere cannoni in cima alla gabbia di vedetta..."},{"a":"carpenter","t":"Ma ritengo che il risultato finale sia più che soddisfacente, non credi?"},{"a":"polonia","t":"Può andare. Ecco i tuoi dobloni, te li sei meritati."},{"a":"carpenter","t":"Ci puoi giurare! Un'ultima cosa. Anche se sono un mastro carpentiere, tutto quel che riguarda stoffe e tessuti sfugge alla mia comprensione."},{"a":"carpenter","t":"E senza vele, la tua nave non andrà da nessuna parte!"},{"a":"polonia","t":"Hai già reso orgogliosa il tuo capitano, mozzo. Ho una vela proprio qui con me."},{"a":"carpenter","t":"Wow! Questa sì che è un'opera d'arte! Anche magica! Dove l'hai presa?"},{"a":"polonia","t":"Un cimelio di nonno Baross. È la vela della sua nave, la Bonaventura!"},{"a":"carpenter","t":"Capisco! Un tocco finale notevole per questo veliero."},{"a":"carpenter","t":"Bene, Capitan Polonia, la Smagliante Allan è tua!"},{"a":"polonia","t":"L'hai battezzata Smagliante Allan? Aspetta un attimo..."},{"a":"polonia","t":"Quella polena... sei tu? E ti raffigura con le natiche al vento?!"},{"a":"carpenter","t":"Ahahah! Non riuscivo a pensare a nessun'altra immagine adatta ad adornare una nave tanto perfetta!"}]},{"id":"polonia_b","i":5,"title":"Darsela a gambe","req":"polonia:5","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"polonia","t":"Ehilà, tu."},{"a":"wood","t":"Sì?"},{"a":"polonia","t":"Mozzami la gamba."},{"a":"wood","t":"Va bene."},{"a":"polonia","t":"Ho detto... aspetta, non è un problema per te?"},{"a":"wood","t":"No, certo. Mantienila ferma, così. Questa vecchia ascia dovrebbe fare al caso tuo."},{"a":"polonia","t":"Err, aspetta un attimo!"},{"a":"wood","t":"Non sarà indolore, ma tu sembri una tipa tosta, non è così?"},{"a":"wood","t":"Assicurati soltanto di usare un buon laccio emostatico... Non vorrai morire dissanguata!"},{"a":"polonia","t":"Basta così! Restiamo calmi!"},{"a":"polonia","t":"Io... la mia nave sta per salpare! N-Non posso trattenermi... Ci vediamo!"},{"a":"wood","t":"Ah, umani. Mai un momento di noia."}]},{"id":"polonia_06","i":6,"title":"Eredità marinaresca","req":"polonia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"Vostra maestà, porto grevi notizie."},{"a":"king","t":"Oh no! Non dirmi che la Città d'oro perduta è rimasta a secco di oro!"},{"a":"sia","t":"Non così grevi, grazie al cielo."},{"a":"sia","t":"Tuttavia, devo informarvi che una feroce pirata ha preso di mira la flotta mercantile del nostro regno."},{"a":"sia","t":"Il bottino da lei catturato finora ammonta a più di 100 miliardi d'oro!"},{"a":"king","t":"Per la dea! Che è successo alle impeccabili difese magiche contro i pirati di cui dispone la mia flotta?"},{"a":"sia","t":"Tragicamente inefficaci, si direbbe. Proprio com'era per il grande Baross, anche questa nave pirata sembra in grado di sottrarsi alla nostra magia..."},{"a":"sia","t":"Dopo aver razziato l'oro, svanisce nelle vastità dell'oceano."},{"a":"king","t":"Che barbarità! E che ne è della ciurma?"},{"a":"sia","t":"Viene sempre risparmiata, vostra maestà. A patto che non opponga resistenza."},{"a":"king","t":"In tal caso, l'oro è un piccolo prezzo da pagare. Sulla mia tavola ci saranno solo pasti da bifolco finché la mia fortuna non sarà ristabilita!"},{"a":"king","t":"Quanto tempo sarà necessario?"},{"a":"sia","t":"Circa 2 giorni, vostra maestà."},{"a":"king","t":"Sarà un duro periodo di sacrifici..."}]},{"id":"polonia_07","i":7,"title":"Abbandonare le rive","req":"polonia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho! Approda Capitan Polonia! Tutti a bere, offro io!"},{"a":"tavern","t":"Polonia! O forse dovrei dire... Capitan Polonia! Suppongo che i tuoi \"affari\" vadano bene?"},{"a":"polonia","t":"A meraviglia! Questi mari sono carichi di bottino pronto a cadere nelle nostre reti!"},{"a":"polonia","t":"Ovunque sia diretta la mia nave, le vele del nonno sembrano avere sempre il vento a favore!"},{"a":"tavern","t":"Baross sarebbe sicuramente fiero di te. Cosa te ne farai di questi tuoi nuovi... \"acquisti\"?"},{"a":"polonia","t":"Ciò che farebbe qualsiasi pirata degno di questo nome! Li seppellirò qua e là assieme alla mia ciurma."},{"a":"tavern","t":"Oooh! Mappe del tesoro! Avvincente!"},{"a":"polonia","t":"Ahrr, così si comportano i veri pirati! Bisogna fare scorte per i mesi invernali, come scoiattoli d'acqua dolce."},{"a":"tavern","t":"E il resto?"},{"a":"polonia","t":"L'ho regalato a quella signora del tempio così carina."},{"a":"tavern","t":"Una donazione all'orfanotrofio? Non ti facevo così generosa!"},{"a":"polonia","t":"Orfanoche?"},{"a":"tavern","t":"Ah, nulla, come non detto. Cosa posso portarti, capitano?"},{"a":"polonia","t":"Un bell'intruglio salmastro, è il mio preferito! E per tutti i marinai d'acqua dolce che credono di poterne buttare giù uno anche loro..."},{"a":"polonia","t":"Il prossimo giro lo offro io! La famiglia Baross è tornata a seminare terrore sui mari! Yo ho ho!"}]},{"id":"polonia_08","i":8,"title":"Sussurri dal passato","req":"polonia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"polonia","t":"Pronto per tuffarti di nuovo negli abissi, tritone?"},{"a":"baker","t":"Certo, capitana! Anche se devo ammettere che..."},{"a":"baker","t":"Sebbene sia sempre felice di aiutarti a esplorare il mondo sottomarino, non ho mai acconsentito a diventare un pirata!"},{"a":"polonia","t":"Non ti preoccupare, compare! Siamo qui per una missione esplorativa. La tua capitana vuole espandere il proprio territorio."},{"a":"polonia","t":"Niente pirateria oggi. Ma, se saremo fortunati, potremmo trovare un relitto da saccheggiare! Yo oh oh!"},{"a":"baker","t":"Ehm, capitana? Che cos'è quella nave all'orizzonte?"},{"a":"polonia","t":"Argh! Calma le pinne, tritone! Sarà la Bonaventura! La nave di mio nonno."},{"a":"baker","t":"Ne sei sicura? Sembra piuttosto malconcia..."},{"a":"polonia","t":"... Per la barba di Nettuno! È-è davvero la Bonaventura! M-ma è impossibile! Mio nonno è morto da un sacco di tempo!"},{"a":"polonia","t":"C-ciurma! Cambio di programma! INSEGUIREMO QUELLA NAVE!"}]},{"id":"polonia_09","i":9,"title":"La deriva di una leggenda","req":"polonia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"baker","t":"... In vita mia non avrei mai immaginato di abbordare una nave così malridotta."},{"a":"polonia","t":"Occhio a dove metti i piedi, tritone. Questa nave è in pessime condizioni."},{"a":"baker","t":"A essere sincero, preferirei di gran lunga farmi una nuotata! Ma poi... Che cosa ci facciamo su questa nave?"},{"a":"polonia","t":"In che senso \"che cosa ci facciamo\"? Questa è la Bonaventura di Baross!"},{"a":"polonia","t":"Devo scoprire che cos'è successo qui... Questa nave non dovrebbe solcare i mari..."},{"a":"baker","t":"La definirei piuttosto \"nave fantasma\"..."},{"a":"polonia","t":"Argh, non spaventarmi così! I fantasmi non esistono!"},{"a":"baker","t":"E invece gli zo..."},{"a":"polonia","t":"C-chiudi quelle branchie, compare! Sto cercando degli indizi."},{"a":"baker","t":"Questo diario ha un aspetto inquietante..."},{"a":"polonia","t":"Arrrgh, il diario di bordo del capitano!"},{"a":"baker","t":"Sembra quasi che ci stia fissando... Non trovi?"},{"a":"polonia","t":"Tu vieni con me, diario. Tieni i tuoi occhi da pirata ben aperti alla ricerca di qualsiasi altra cosa."},{"a":"polonia","t":"... Compare, puoi smetterla di toccarmi i capelli?"},{"a":"baker","t":"Capitana, ma io sono qui."},{"a":"polonia","t":"... AAARGH!!! Abbandonare la nave!"}]},{"id":"polonia_10","i":10,"title":"Eredità piratesca","req":"polonia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"polonia","t":"La vostra capitana è di nuovo a bordo, ciurma. Issate le vele, ce ne andiamo."},{"a":"baker","t":"Capitana, guarda! La Bonaventura sta affondando!"},{"a":"polonia","t":"Per mille cirripedi! Com'è possibile? Dopo tutto questo tempo?! Era il diario a tenerla ancora a galla?"},{"a":"baker","t":"... Forse ha raggiunto il suo scopo."},{"a":"polonia","t":"Baross, vecchio lupo di mare... Come poteva sapere...?"},{"a":"baker","t":"Polonia, il diario di bordo?"},{"a":"polonia","t":"Hai ragione, fammi dare un'occhiata."},{"a":"polonia","t":"..."},{"a":"polonia","t":"... Ho un altro favore da chiederti, tritone."},{"a":"baker","t":"Ah, sì. Lascia che te lo legga io."},{"a":"baker","t":"Uhm... Sembrano istruzioni per trovare un qualche luogo degli abissi."},{"a":"polonia","t":"Il Tempio sommerso? Sai che novità."},{"a":"baker","t":"No, sembra si tratti di un luogo molto più lontano... Dice qualcosa sulla Città d'oro perduta, credo..."},{"a":"baker","t":"La Città d'oro perduta non si trova sott'acqua, però..."},{"a":"polonia","t":"I-intendi dire che non era una storia? Quel posto è reale?"},{"a":"polonia","t":"Tritone, tu sai nuotare. Dev'essere il destino."},{"a":"polonia","t":"Se le storie sono vere... non ti pentirai di avermi condotta lì."}]},{"id":"polonia_11","i":11,"title":"La Città d'oro sommersa","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"baker","t":"Fiuu! Siamo arrivati! Come stai, capitana?"},{"a":"polonia","t":"*Coff* *coff*..."},{"a":"polonia","t":"Per la miseria... Hai... hai delle gambe forti... per essere un tritone..."},{"a":"baker","t":"E per fortuna! Quest'ingresso è così in profondità che penso che nessun umano potrebbe raggiungerlo."},{"a":"polonia","t":"Hai ragione! Stavo per annegare. Non tornerò mai più quaggiù..."},{"a":"baker","t":"Per la dea! Polonia, guardati intorno!"},{"a":"polonia","t":"Per mille cirripedi... La Città d'oro sommersa..."},{"a":"polonia","t":"Questo posto... Non ho mai visto nulla di simile."},{"a":"baker","t":"Trabocca di tesori! Oro, perle... La Città d'oro perduta sembra un posto da poveracci al confronto!"},{"a":"polonia","t":"Mio nonno ha cercato questo luogo per tutta la vita..."},{"a":"baker","t":"Alla fine non è riuscito a portare nulla a terra, così ha lasciato tutto qui per la sua nipotina preferita."},{"a":"polonia","t":"Sniff... Mi viene da piangere..."},{"a":"baker","t":"Vuoi che ti lasci un momento, capitana?"},{"a":"polonia","t":"Scherzi?! C'è così tanto da saccheggiare! E tu sei appena stato promosso a Primo ufficiale. Pronto per altre nuotatine?"},{"a":"baker","t":"Devo portare sacchi pieni di bottino E una pirata? Meglio che faccia un po' di stretching!"}]},{"id":"polonia_epilogue","i":12,"title":"Epilogo","req":"polonia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"polonia","t":"Uhm..."},{"a":"baker","t":"Ci stiamo preparando per un'altra immersione, Polonia?"},{"a":"polonia","t":"No, compare. Ho un grosso problema."},{"a":"polonia","t":"Ho troppi soldi! Sto quasi finendo le spiagge in cui seppellirli."},{"a":"baker","t":"Devo dire che anch'io sono un po' sopraffatto dalla mia quota!"},{"a":"baker","t":"Ah, a proposito!"},{"a":"baker","t":"Prima sono andato a fare una nuotata intorno alla Bonaventura affondata..."},{"a":"baker","t":"Non c'era nulla degno di nota, ma ho trovato questa benda. La riconosci?"},{"a":"polonia","t":"Primo ufficiale! Quella è la benda di Baross!"},{"a":"polonia","t":"Yo oh oh! Sono così felice che potrei baciarti!"},{"a":"baker","t":"Il piacere è tutto mio, capitana. Sono sicuro che è quello che avrebbe voluto tuo nonno."},{"a":"polonia","t":"... Sai una cosa? Ho chiuso con tutti questi saccheggi subacquei."},{"a":"polonia","t":"Il mare è la casa dei pirati, non una città d'oro! Non importa quanti tesori nasconda tra le onde."},{"a":"polonia","t":"Come nipote del grande Baross, ti dono la Città d'oro sommersa e tutto il bottino rimasto."},{"a":"polonia","t":"Grazie per i tuoi servigi, Primo ufficiale. Se mai dovessi cambiare idea sulla pirateria, sarai il benvenuto tra noi."},{"a":"baker","t":"Grazie, capitana. Non dimenticherò mai le nostre avventure insieme!"},{"a":"baker","t":"... Immagino che quando tornerò a casa farò meglio a parlare con Tutu Mano di quella vacanza!"}]}]},{"id":"king","name":"Reinhold","chapters":[{"id":"king_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"sia","t":"Re Reinhold..."},{"a":"king","t":"Oh... Pare che i miei doveri mi abbiano trovato!"},{"a":"sia","t":"I vostri doveri consistono in un lungo elenco di arretrati. La corte vi attende."},{"a":"king","t":"Arrivederci, negoziante! Tornerò presto!"},{"a":"sia","t":"Sarebbe preferibile di no."}]},{"id":"king_01","i":1,"title":"La corte del re","req":"king:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"king","t":"La corte del re è aperta! Chi ha richieste si faccia avanti!"},{"a":"rudo","t":"Umpf."},{"a":"king","t":"Cosa pensi debba fare il regno di Reinhold per i suoi sudditi, grosso... uomo orso?"},{"a":"rudo","t":"Tutta la magia andrebbe proibita e gli incantatori dovrebbero essere esiliati."},{"a":"king","t":"Ah... Beh, questo... Ehm..."},{"a":"king","t":"Noi... terremo in considerazione la tua proposta! Avanti il prossimo!"},{"a":"herbs","t":"Salveee! Penso che ogni singolo giorno andrebbe proclamato GIORNO DELLA PIGNATTA!"},{"a":"king","t":"Che idea magnifica! In effetti, potremmo..."},{"a":"sia","t":"..."},{"a":"king","t":"... passare molte settimane a discutere questa proposta! Grazie per il tuo contributo!"},{"a":"king","t":"Sia, a quante altre persone dobbiamo dare udienza?"},{"a":"sia","t":"Altre cinquantacinque, mio re."},{"a":"king","t":"Oh, cielo."}]},{"id":"king_02","i":2,"title":"Sciocco dal cuore d'oro","req":"king:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"donovan","t":"Chiedo scusa, è libero questo posto?"},{"a":"sia","t":"Sei qui per avvelenare la mia giornata, Donovan?"},{"a":"donovan","t":"Mi ferisci, Sia. Non desidero altro che trascorrere un po' di tempo con una compatriota imperiale."},{"a":"donovan","t":"Come se la passa il nostro sciocco re?"},{"a":"sia","t":"Ormai non sei granché come spia, Donovan. Reinhold non è affatto sciocco come credi."},{"a":"sia","t":"Anche se il suo sorriso lo nasconde, fa molti sacrifici per la sua gente."},{"a":"sia","t":"L'imperatore... Il NOSTRO imperatore... Potrebbe imparare molto da lui."},{"a":"sia","t":"Il mio ruolo consiste soltanto nell'impedirgli di rovinarsi in nome del suo popolo."},{"a":"donovan","t":"È davvero così? Affascinante."},{"a":"sia","t":"Può essere uno sciocco dal cuore d'oro, sì. Ma non lo sottovaluterei se fossi in te."}]},{"id":"king_03","i":3,"title":"Straordinari a corte","req":"king:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"king","t":"Uff, questa pila di rapporti sembra non finire mai, eh?"},{"a":"sia","t":"Temo che dobbiamo prepararci a un'altra nottata."},{"a":"king","t":"Grazie per l'aiuto che mi stai dando, Sia!"},{"a":"sia","t":"Di nulla, mio re. Dunque, passiamo al prossimo rapporto..."},{"a":"sia","t":"I contadini di Southburg non hanno potuto pagare tutte le tasse, poiché il raccolto è andato molto male quest'anno."},{"a":"sia","t":"Credo che sia la seconda volta di fila che succede..."},{"a":"king","t":"Invia i miei maghi di corte a indagare. Forse una maledizione ha reso poco fertili le loro terre!"},{"a":"sia","t":"Una soluzione molto generosa."},{"a":"king","t":"E condoniamo di nuovo le loro tasse, è quello che avrebbe fatto mio padre!"},{"a":"sia","t":"Bene. Anche io credo che re Keinan avrebbe fatto lo stesso."},{"a":"king","t":"La corona che mi ha lasciato è davvero pesante..."},{"a":"king","t":"Cosa dice il prossimo rapporto?"},{"a":"sia","t":"Parla di tensioni crescenti ai confini con l'impero..."}]},{"id":"king_04","i":4,"title":"Ospiti dall'ombra","req":"king:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"king","t":"..."},{"a":"sia","t":"Mio re..."},{"a":"king","t":"Aaah!"},{"a":"king","t":"Annuncia la tua presenza la prossima volta, invece di apparirmi alle spalle!"},{"a":"sia","t":"Il ricordo dell'attentato di quel ninja è ancora molto vivido, non è così?"},{"a":"king","t":"Certamente! Sono sopravvissuto per un pelo!"},{"a":"sia","t":"Devo raddoppiare il numero di guardie?"},{"a":"king","t":"No... Non è necessario. Ma muoviti meno silenziosamente in futuro!"},{"a":"sia","t":"Certo, mio re."},{"a":"hemma","t":"Ah, è bello essere a casa... Uh?"},{"a":"king","t":"ARGH! N-Ninja!?"},{"a":"hemma","t":"Chiediamo scusa, pare che abbiamo mancato il bersaglio."},{"a":"hemma","t":"Viaggiare tra le ombre può condurre a risultati inaccurati, ogni tanto."},{"a":"king","t":"TELETRASPORTARSI DALL'OMBRA nella mia sala del trono è strettamente proibito da oggi in poi!"},{"a":"sia","t":"Re Reinhold? Tutto bene?"},{"a":"king","t":"Sì! Mostra dov'è l'uscita a questo... spettrale visitatore."},{"a":"sia","t":"Certamente. Mi assicurerò che il castello sia adeguatamente protetto contro simili intrusioni, in futuro."},{"a":"hemma","t":"Abbiamo trovato un punto d'arrivo piuttosto divertente. Torneremo di certo."},{"a":"king","t":"Mi auguro davvero di no!"}]}]},{"id":"rudo","name":"Rudo","chapters":[{"id":"rudo_01","i":1,"title":"La montagna vivente","req":"rudo:1","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"Brrr... I miei abiti sono troppo leggeri per questo freddo! Perché siamo venuti qui?"},{"a":"lilu","t":"Le gemme che si trovano in questo luogo hanno proprietà fantastiche! Grimar mi ha detto che..."},{"a":"argon","t":"Aspetta, Lilu, guarda! Laggiù c'è un uomo che combatte contro uno yeti!"},{"a":"lilu","t":"Un uomo?! Ma è grosso quanto una montagna!"},{"a":"lilu","t":"E ha... schienato lo yeti con un suplex?!"},{"a":"rudo","t":"Fiuuu... E con questo siamo a dieci."},{"a":"argon","t":"Un combattimento formidabile, signore! Sei stato magnifico!"},{"a":"rudo","t":"Uh?"},{"a":"lilu","t":"Signore... sei ferito! Lascia che ti guarisca!"},{"a":"lilu","t":"<c1>Gua</c1>...!"},{"a":"rudo","t":"STA' INDIETRO!"},{"a":"rudo","t":"Sto bene. La ferita guarirà da sola."},{"a":"rudo","t":"Questo non è un posto per ragazzini. Tornatevene a casa."},{"a":"argon","t":"Caspita, quel tizio la odia proprio la magia, eh?"},{"a":"lilu","t":"No. Quel che ho visto nei suoi occhi... era paura."}]},{"id":"rudo_02","i":2,"title":"Avviso di sfratto","req":"rudo:2","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"elderowen","t":"Temo di non capire..."},{"a":"rudo","t":"Bah! Apri bene le orecchie, vecchiaccio, te lo dirò in parole semplici!"},{"a":"rudo","t":"Lo stregone di questa città è un pazzo furioso e andrebbe mandato via a calci nel sedere per il bene di tutti."},{"a":"elderowen","t":"Santo cielo... Mi sembra un giudizio un po' affrettato."},{"a":"rudo","t":"Non più tardi di ieri mi ha detto di tenere d'occhio Timotheus..."},{"a":"rudo","t":"Sosteneva che \"Tim\" era confuso e in preda alle allucinazioni e che non andava perso di vista neanche un secondo."},{"a":"rudo","t":"Ma Timotheus è *LUI*!"},{"a":"elderowen","t":"Mmh, sì. Capisco."},{"a":"elderowen","t":"A dispetto della sua... \"condizione\", Timotheus Grimar è parte integrante di questa città."},{"a":"elderowen","t":"È tanto disponibile quanto innocuo. Non vedo ragione di allarmarsi."},{"a":"lilu","t":"Cos'è questa storia di cacciare Mastro Grimar?!"},{"a":"rudo","t":"Tu stanne fuori, ragazzina."},{"a":"lilu","t":"No! Mastro Grimar è uno stregone potente, ma non farebbe male neppure a una mosca!"},{"a":"rudo","t":"Bah! E va bene! Ma se fa saltare in aria la città, non dite che non vi avevo avvisati."},{"a":"elderowen","t":"Quel tipo è davvero un piantagrane."},{"a":"lilu","t":"Sarà meglio che lo tenga d'occhio..."}]},{"id":"rudo_03","i":3,"title":"Nati con la Scintilla","req":"rudo:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"priest","t":"Chiedo scusa, ma... Cos'hai da borbottare?"},{"a":"rudo","t":"Maledizione. Questa dannata città pullula di incantatori..."},{"a":"priest","t":"Ah... Tu devi essere Rudo, se non sbaglio."},{"a":"rudo","t":"Non cercare di fare la simpatica con me, stregaccia."},{"a":"priest","t":"Io sono una Sacerdotessa della Dea. I miei poteri sono diversi da quelli di una strega."},{"a":"priest","t":"Ho fatto voto di dedicare la mia vita a curare e proteggere gli altri."},{"a":"rudo","t":"Non ci casco. Voi Nati-con-la-Scintilla siete tutti uguali."},{"a":"priest","t":"Tu sai della Scintilla...?"},{"a":"rudo","t":"Umpf. Lascia perdere, me ne vado."},{"a":"priest","t":"Hai sentito, Lilu?"},{"a":"lilu","t":"Sissignora, ho sentito tutto!"},{"a":"priest","t":"Ricordi le mie lezioni sulla Scintilla?"},{"a":"lilu","t":"Certo! Solo le persone nate con la Scintilla possono controllare la magia e lanciare incantesimi."},{"a":"lilu","t":"In genere, però, le persone comuni ignorano questo fatto."},{"a":"priest","t":"Risposta esatta! Non che mi aspettassi nulla di diverso dalla mia allieva più brillante!"},{"a":"priest","t":"Il che ci porta alla domanda: come faceva lui a saperlo...?"},{"a":"lilu","t":"Mmh... Pensi che...?"}]},{"id":"rudo_04","i":4,"title":"Spacca e arraffa","req":"rudo:4","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"polonia","t":"Yo ho ho! Capitan Polonia ha fatto un colpo bello grosso, stavolta!"},{"a":"polonia","t":"Un'intera tomba reale, pronta a essere saccheggiata!"},{"a":"rudo","t":"Silenzio, marinaretta. Sono impegnato."},{"a":"polonia","t":"Un colpo grosso... se solo un dannato berserker non stesse FACENDO A PEZZI TUTTO IL BOTTINO!"},{"a":"polonia","t":"Per mille palle di cannone, qual è il tuo problema? Questa roba vale dobloni a palate!"},{"a":"rudo","t":"È roba antica."},{"a":"rudo","t":"Magica."},{"a":"rudo","t":"E sicuramente maledetta."},{"a":"rudo","t":"La sto facendo a pezzi per risolvere il problema alla radice."},{"a":"rudo","t":"Se in città sono troppo stolti per vedere il problema, non mi resta che occuparmene personalmente."},{"a":"polonia","t":"Ehi, aspetta. Quel bastone sembra DAVVERO prezioso. Non vorrai mica..."},{"a":"rudo","t":"Umpf."},{"a":"rudo","t":"Ahia."},{"a":"polonia","t":"Per tutti i kraken! Non spezzarlo con il ginocchio!"},{"a":"polonia","t":"Anche se sembra che sia stato il bastone a spezzare il ginocchio. Non lo hai nemmeno scalfito!"},{"a":"polonia","t":"Come va la gamba, compare?"},{"a":"rudo","t":"Bene, ma questo bastone è più duro di quanto sembra."},{"a":"rudo","t":"E per qualche motivo non riesco a posarlo. È come... incollato alla mia mano."},{"a":"polonia","t":"Non sono certo il medico della nave, ma la mia diagnosi è che tu ti sia maledetto da solo, amico."},{"a":"polonia","t":"Faresti meglio a farti vedere!"},{"a":"rudo","t":"Una maledizione magica. Ovvio. Il problema è SEMPRE una maledizione."},{"a":"rudo","t":"D'accordo, allora io vado. Finisci tu di scassare tutto il resto."},{"a":"polonia","t":"Agli ordini, compare!"},{"a":"polonia","t":"... Ma l'unico scasso sarà quello che farò per rubare tutto!"}]},{"id":"rudo_a","i":4,"title":"Violenta passione","req":"rudo:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"herbs","t":"Gorza!"},{"a":"gems","t":"Gorza!<sprite tint=1 name=Note2>"},{"a":"wood","t":"Juniper! Maylee! Che succede?"},{"a":"herbs","t":"Io e Maylee stavamo parlando del suo futuro principe azzurro..."},{"a":"gems","t":"Non vedo l'ora!"},{"a":"herbs","t":"E ci stavamo chiedendo... tu come hai incontrato il tuo?"},{"a":"wood","t":"Quell'imbranato di Rudo? Oh!"},{"a":"wood","t":"Non lo si direbbe a guardarlo, ma sa davvero come parlare a una signora."},{"a":"wood","t":"Vediamo... È andata più o meno così..."},{"a":"rudo","t":"... E un ultimo sorso prima di andare!"},{"a":"tavern","t":"Rudo... Hai mai pensato di mettere radici?"},{"a":"rudo","t":"Fatti gli affari tuoi, Naya. Non ho tempo per queste sciocchezze."},{"a":"tavern","t":"L'amore arriva quando meno te lo aspetti! Chi lo sa, magari la donna dei tuoi sogni è qui proprio adesso..."},{"a":"rudo","t":"Bah! Per avere la mia attenzione, una donna deve come minimo riuscire a mettermi KO!"},{"a":"wood","t":"È una sfida, omaccione?"},{"a":"rudo","t":"Fatti avanti, dentona!"},{"a":"tavern","t":"Gorza, metti giù quella sedia, per..."},{"a":"wood","t":"Che dici, testone? Ti basta o ne vuoi ancora?"},{"a":"rudo","t":"RAAARGH!!!"},{"a":"wood","t":"Wow!"},{"a":"wood","t":"... E la settimana successiva ci siamo sposati. Il matrimonio più sanguinolento della storia."},{"a":"herbs","t":"..."},{"a":"gems","t":"..."},{"a":"herbs","t":"... Forse faremo meglio a chiedere a qualcun altro."}]},{"id":"rudo_05","i":5,"title":"Maledizioni e imprecazioni","req":"rudo:5","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"rudo","t":"Non puoi romperla? In che senso?"},{"a":"master","t":"Hai capito bene, mio violento amico: non posso rompere questa reliquia."},{"a":"rudo","t":"A che serve un martello adamantino se non può distruggere un misero bastone?!"},{"a":"master","t":"Non lo chiamerei misero... A me sembra piuttosto cattivo!"},{"a":"master","t":"E credo ci sia dell'altro all'opera qui... Magia, probabilmente."},{"a":"rudo","t":"Magia. OVVIAMENTE."},{"a":"rudo","t":"C'è sempre una maledizione magica di mezzo."},{"a":"master","t":"Ma allora lo sapevi già! Perché non sei andato da qualcuno esperto di queste cose, invece che da me?"},{"a":"rudo","t":"Non ci si può fidare dei maghi... Per niente."},{"a":"master","t":"Non credo tu abbia scelta, figliolo."},{"a":"master","t":"E poi come puoi non fidarti di Lilu? È così adorabile!"},{"a":"rudo","t":"Ma è una maga, no? Quindi è come tutti gli altri."},{"a":"rudo","t":"Pericolosa. Diabolica. MALVAGIA."},{"a":"master","t":"Beh, ma è anche l'unica che può aiutarti, se vuoi davvero liberarti di questo bastone."},{"a":"rudo","t":"Dannazione."}]},{"id":"rudo_06","i":6,"title":"Un ignaro mago","req":"rudo:6","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"rudo","t":"Naya, il solito."},{"a":"tavern","t":"Mi spiace Rudo, le armi non sono ammesse. Sai come funziona."},{"a":"rudo","t":"Parli di questo? È un bastone da passeggio."},{"a":"tavern","t":"Non penso proprio! È difficile non riconoscere un bastone magico."},{"a":"rudo","t":"Bah. E va bene. Vedi? È maledetto. Non posso toglierlo."},{"a":"tavern","t":"Oh cielo! Allora faremo una piccola eccezione, solo per te!"},{"a":"rudo","t":"Umpf. Grazie."},{"a":"tavern","t":"Cosa farai per quella maledizione, quindi?"},{"a":"rudo","t":"Me ne infischierò. Andrò per la mia strada senza badarci."},{"a":"tavern","t":"Davvero? Ti rende alquanto scontroso, oserei dire. Addirittura più scontroso del solito, se possibile."},{"a":"tavern","t":"E poi, a vederti, tutti penserebbero che sei un mago di qualche tipo."},{"a":"rudo","t":"... Davvero? Un maledetto mago?"},{"a":"tavern","t":"Ti manca solo uno di quei buffi cappelli! E un carattere migliore!"},{"a":"rudo","t":"... Mi sa che hai ragione. Devo proprio farci qualcosa. Ci vediamo."},{"a":"tavern","t":"Buona giornata! Te lo aggiungo al conto!"}]},{"id":"rudo_07","i":7,"title":"Sentore di turbamento","req":"rudo:7","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"rudo","t":"Mi dispiace per prima. Mi hanno detto che puoi... aiutarmi a liberarmi di questa maledizione."},{"a":"lilu","t":"Il bastone, eh? Sembra proprio maligno."},{"a":"lilu","t":"Non ho mai provato a cancellare una maledizione prima d'ora, ma in teoria... dovrei esserne in grado."},{"a":"lilu","t":"Sei sicuro di essere pronto? Sei molto teso."},{"a":"rudo","t":"... Sì."},{"a":"lilu","t":"Ok! Fammi concentrare..."},{"a":"lilu","t":"Vedo la maledizione... avvolgerti completamente."},{"a":"lilu","t":"Abbi pazienza, dovrò andare più a fondo..."},{"a":"rudo","t":"... Argh!"},{"a":"lilu","t":"Uoah!"},{"a":"lilu","t":"Sembrava PROPRIO che tu stessi per tirarmi un pugno!"},{"a":"rudo","t":"... Scusa. Non volevo."},{"a":"lilu","t":"Non credo stia funzionando. Devo concentrarmi bene, capisci?"},{"a":"rudo","t":"Certo, scusa, colpa mia. Cercherò un altro metodo."},{"a":"lilu","t":"Perché non chiedere a Malady? Magari riesce a capire cose che io non vedo nemmeno."},{"a":"rudo","t":"Malady, eh? Farò un tentativo."},{"a":"lilu","t":"Comportati bene! Ha delle... condizioni particolari di cui dovresti essere a conoscenza..."}]},{"id":"rudo_08","i":8,"title":"Maledizione per due","req":"rudo:8","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"rudo","t":"Signora Malady, hai un attimo per parlare?"},{"a":"malady","t":"(Oh no, Lilu mi aveva avvisato...)"},{"a":"malady","t":"Mh... Mi spiace, temo di..."},{"a":"rudo","t":"Scusami, non volevo spaventarti. Pensavo che magari sapessi qualcosa di questo bastone."},{"a":"malady","t":"... Pensavo che odiassi la magia?"},{"a":"rudo","t":"Più di ogni altra cosa al mondo."},{"a":"rudo","t":"Ma anche tu sei maledetta, no? Proprio come me."},{"a":"rudo","t":"Non hai scelto la magia. Non è colpa tua."},{"a":"malady","t":"... Se è così, posso provare a... parlare con il bastone."},{"a":"malady","t":"..."},{"a":"malady","t":"... Sembra un parassita. Si ciba della tua Scintilla."},{"a":"rudo","t":"È senziente?"},{"a":"malady","t":"Sì... in un certo senso."},{"a":"malady","t":"La tua Scintilla è estremamente forte. Potrebbero volerci decenni, ma..."},{"a":"malady","t":"... Forse può liberarti dalla tua magia...?"},{"a":"rudo","t":"Umpf, non ci giurerei."},{"a":"rudo","t":"Quindi quello che vuole è un babbeo da cui succhiare magia, giusto?"},{"a":"malady","t":"Uhm... sì. Più o meno."},{"a":"malady","t":"Ah, ti prego. Tanto la maledizione c'è già..."},{"a":"rudo","t":"Ah! Non mi è passato nemmeno per l'anticamera del cervello."},{"a":"rudo","t":"Grazie per l'aiuto. Penso di avere un'idea..."}]},{"id":"rudo_09","i":9,"title":"Il passato di un soldato","req":"rudo:9","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"malady","t":"Ehm... posso entrare?"},{"a":"veteran","t":"Ah, la Medusa di cui ho tanto sentito parlare."},{"a":"veteran","t":"Benvenuta, recluta. Mi dispiace, non ho sedie adatte alla tua stazza."},{"a":"malady","t":"Non importa... Grazie. Volevo chiederti di più su Rudo."},{"a":"veteran","t":"Quell'imbranato? Non ti ha mica dato fastidio, vero?"},{"a":"malady","t":"No, è stato... stranamente gentile con me."},{"a":"veteran","t":"Davvero? Strano, sembra proprio odiare la magia."},{"a":"malady","t":"È per questo che sono qui. Volevo sapere... Perché?"},{"a":"veteran","t":"Un tempo facevamo parte dell'esercito dell'Impero. Siamo vecchi compagni d'arme."},{"a":"veteran","t":"Rudo è stato... \"offerto volontario\" per un esperimento. Volevano impiantare artificialmente la Scintilla nei soldati."},{"a":"veteran","t":"È stata una brutta storia. Rudo è cambiato da quel momento."},{"a":"malady","t":"È terribile... "},{"a":"veteran","t":"Ed è ancora peggio di quello che sembra. Noi siamo fuggiti appena abbiamo potuto."},{"a":"malady","t":"Almeno ha... funzionato? Ho percepito una Scintilla estremamente forte dentro di lui..."},{"a":"veteran","t":"Non saprei dirti. Hai visto com'è. Nemmeno l'imperatore in persona potrebbe convincerlo a fargli lanciare un incantesimo."},{"a":"malady","t":"E ora... per colpa di questa storia, è colpito da una terribile maledizione... Come possiamo aiutare?"},{"a":"veteran","t":"È venuto da te, no? Il fatto che abbia chiesto aiuto è un buon segno! "},{"a":"veteran","t":"Non è la persona più intelligente del mondo, ma è tenace. Se la caverà."}]},{"id":"rudo_10","i":10,"title":"Passaggio di proprietà","req":"rudo:10","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"rudo","t":"Bene, stecchino che non sei altro. Ti propongo un affare."},{"a":"rudo","t":"Ti darò a quel goblinello laggiù."},{"a":"monster_Forest_Blacksmith","t":"I-iiih! Lasciami... andare!"},{"a":"rudo","t":"Diventate migliori amici e ci dimentichiamo di tutto quello che è successo."},{"a":"rudo","t":"Se non ti va..."},{"a":"rudo","t":"Faccio un bel tuffo nella lava e vediamo chi resiste di più."},{"a":"rudo","t":"Hai deciso? L'\"acqua\" sembra piacevole, se vuoi la mia opinione."},{"a":"monster_Forest_Blacksmith","t":"..."},{"a":"rudo","t":"... Ottima scelta. Buon divertimento, goblinello."},{"a":"monster_Forest_Blacksmith","t":"Ugh! È... bloccato!"},{"a":"rudo","t":"Buah ah ah! Addio!"}]},{"id":"rudo_epilogue","i":11,"title":"Epilogo","req":"rudo:11","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"lilu","t":"Rudo! Era ora..."},{"a":"rudo","t":"Uhm?"},{"a":"lilu","t":"Oh! Non hai più il bastone!"},{"a":"rudo","t":"Esatto. Un peso in meno da portarsi dietro."},{"a":"rudo","t":"... Mi dispiace per l'ultima volta. Avevo i nervi a fior di pelle."},{"a":"lilu","t":"... Immagino di poterti perdonare. Ma dovrai lavorare sul tuo atteggiamento nei confronti dei maghi!"},{"a":"rudo","t":"Ah! Quella Malady è stata incredibilmente utile. Chissà, forse cambierò idea un giorno."},{"a":"lilu","t":"È riuscita a dissolvere la maledizione?"},{"a":"rudo","t":"Non proprio. Ma grazie a lei ho trovato un... aiuto inaspettato là fuori."},{"a":"rudo","t":"Un po' di cooperazione non fa male di tanto in tanto. Ah ah ah!"},{"a":"argon","t":"Ashley, attenta! Sta arrivando qualcosa!"},{"a":"ashley","t":"Sono pronta a tutto! Forza, bestione!"},{"a":"monster_Forest_Blacksmith","t":"... Aiuto..."},{"a":"argon","t":"Uh?"},{"a":"ashley","t":"Uuuuh?"}]}]},{"id":"sia","name":"Sia","chapters":[{"id":"sia_01","i":1,"title":"Primi passi reali","req":"sia:1","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"king","t":"Sia! Ho deciso!"},{"a":"sia","t":"Sì, mio re?"},{"a":"king","t":"Oggi, voglio andare a fare shopping!"},{"a":"sia","t":"Un'idea eccellente, sua maestà."},{"a":"sia","t":"Tuttavia, dando un'occhiata al suo programma, sembra che oggi lei debba incontrare dei dignitari stranieri..."},{"a":"king","t":"Oh, ma che noia! Non possiamo mandarli via?"},{"a":"sia","t":"Le ricordo, mio re, che seppur giovane lei è sempre il sovrano. La sua parola è legge."},{"a":"king","t":"...Hai completamente ragione! Allora shopping sia! Quei dignitari possono attendere!"},{"a":"sia","t":"La sua risolutezza è ammirevole. Posso accompagnarla?"},{"a":"king","t":"Ma certo! Non mi fido di nessun altro per la protezione della mia graziosa persona."}]},{"id":"sia_02","i":2,"title":"Amici dei bassifondi","req":"sia:2","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"...E così, ho motivo di credere che la vita del nostro re sia in pericolo."},{"a":"elderowen","t":"Capisco. In effetti, alcuni regni rivali trarrebbero vantaggio da un attentato alla vita del re."},{"a":"elderowen","t":"Non ho notato alcun individuo sospetto, ma Naya alla taverna potrebbe saperne di più."},{"a":"sia","t":"Grazie, Owen. La tua saggezza e il tuo patriottismo sono molto apprezzati."},{"a":"elderowen","t":"Ma figurati. È mio dovere di cittadino salvaguardare la prosperità del nostro regno."},{"a":"elderowen","t":"Anche se è giovane e sciocco, sono certo che Reinhold diventerà un grande re... a tempo debito."},{"a":"sia","t":"Ed è mio preciso dovere mantenerlo in vita fino ad allora!"},{"a":"tavern","t":"Bene, bene... non si vede spesso la bella gente di sangue blu qui alla taverna!"},{"a":"sia","t":"Falla finita con questa scenetta, Naya, sai bene chi sono."},{"a":"tavern","t":"Proprio così! Sia Leonel, un dono al nostro re da parte dell'imperatore di Kern..."},{"a":"tavern","t":"Per fargli da consigliera... ma anche per tenerlo d'occhio, non è vero?"},{"a":"sia","t":"...!"},{"a":"sia","t":"...Sei proprio un'impicciona, lo sai?"},{"a":"sia","t":"Bene allora, cara Naya la ficcanaso, dimmi..."},{"a":"sia","t":"Hai per caso visto facce strane qui alla taverna, ultimamente?"},{"a":"tavern","t":"Oh, ne abbiamo tante di facce strane! Orchi brilli, negozianti..."},{"a":"tavern","t":"Ma la più strana di tutti è quella ragazza laggiù nell'angolo."},{"a":"yami","t":"...!"},{"a":"sia","t":"È scappata..."},{"a":"sia","t":"Quella era una spia azumana! ...o un'assassina."},{"a":"sia","t":"Devo fare molta attenzione..."}]},{"id":"sia_03","i":3,"title":"L'imbucata","req":"sia:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"Ci siamo riuniti tutti qui, oggi, per festeggiare l'incredibile generosità del re."},{"a":"sia","t":"Nel corso dei mesi passati, egli ha donato svariati milioni in monete d'oro dai suoi forzieri..."},{"a":"sia","t":"...a moltissimi templi, scuole e orfanatrofi della zona."},{"a":"sia","t":"Siete tutti benvenuti alla sua festa, e vi invitiamo a spargere la voce fra amici e parenti."},{"a":"sia","t":"Lunga vita a re Reinhold!"},{"a":"yami","t":"Reinhold il tiranno, il tuo regno termina ora!"},{"a":"king","t":"Aaargh..."},{"a":"sia","t":"Uno shuriken! La spia azumana!"},{"a":"sia","t":"Guardie! Create un perimetro attorno al castello! Nessuno deve fuggire!"},{"a":"sia","t":"Argon, segui l'assassina!"},{"a":"argon","t":"Subito!"},{"a":"sia","t":"Tu! Sudicio buffone! Il re è ferito! Vai immediatamente a cercare un guaritore!"},{"a":"leather","t":"Wow, poco educata, eh?"},{"a":"sia","t":"(Avevo posto ogni punto d'accesso sotto la massima sorveglianza...)"},{"a":"sia","t":"(Ma chi è questa ragazza?)"}]},{"id":"sia_04","i":4,"title":"Lettera bruciata","req":"sia:4","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"Naya la ficcanaso, credo che tu mi debba delle spiegazioni."},{"a":"tavern","t":"Oh, signora Leonel... credo sia TU a dovermi delle spiegazioni."},{"a":"sia","t":"Prego?"},{"a":"tavern","t":"Ho intercettato delle lettere MOLTO interessanti. Inviate da te, mi pare."},{"a":"tavern","t":"Vogliamo leggerle assieme?"},{"a":"sia","t":"...!"},{"a":"tavern","t":"Vediamo, cosa abbiamo qui... un sigillo di Kern e inviate direttamente all'imperatore di Kern?"},{"a":"tavern","t":"Santo cielo! E io che speravo in un intrigo amoroso... ma andrà bene anche il tradimento."},{"a":"sia","t":"N-Naya, per favore, smettila!"},{"a":"tavern","t":"Oh! Ecco qui la parte succosa!"},{"a":"tavern","t":"\"Re Reinhold è un completo idiota, la sua posizione sul trono va a vostro totale vantaggio.\""},{"a":"tavern","t":"\"Mantenerlo in vita danneggerà il suo regno molto più che la sua morte.\""},{"a":"sia","t":"..."},{"a":"tavern","t":"Parole tanto dure sono disdicevoli per la sua consigliera, a parer mio!"},{"a":"sia","t":"Naya... ficcanaso... la pagherai per questo!"},{"a":"tavern","t":"Un giorno, forse. Ma per ora, credo che sarai tu a pagare. E molto, temo."},{"a":"sia","t":"Cadi così in basso da ricorrere al ricatto?"},{"a":"tavern","t":"Un peccatuccio, in confronto al tradimento!"},{"a":"tavern","t":"Se avessi pianificato di fare del male al nostro re, d'altra parte..."},{"a":"sia","t":"Umpf. Molto bene. Dimmi il tuo prezzo. E prega che la mia rete di spie non superi mai la tua in astuzia, Naya."},{"a":"tavern","t":"Non vedo l'ora!"}]},{"id":"sia_a","i":4,"title":"Il capriccio del re","req":"sia:3","reward":{"k":"tokens","id":"tokens","q":3,"n":"Gettoni della fortuna"},"side":true,"lines":[{"a":"sia","t":"Mio re."},{"a":"king","t":"Mia cara Sia! Come posso aiutarti!"},{"a":"sia","t":"È possibile che, di recente, vi siate dedicato a uno dei vostri \"capricci\"?"},{"a":"king","t":"N-No! Ovvio che no! Non sarebbe da me!"},{"a":"sia","t":"Strano. Dai registri risulta che la stanza del tesoro numero 36 sia strapiena di <c1>kunai</c1>."},{"a":"sia","t":"Non credo di dover ricordare a vostra maestà che si tratta di un oggetto molto raro."},{"a":"king","t":"Ci sarà sicuramente una logica spiegaz..."},{"a":"sia","t":"Inoltre, molti dei più antichi oggetti d'antiquariato del regno sono stati visti tra le mani di popolani."},{"a":"sia","t":"La vostra generosità è encomiabile..."},{"a":"sia","t":"Ma vi prego, non distribuite in giro artefatti inestimabili solo per soddisfare i vostri sbalzi d'umore."},{"a":"king","t":"Umpf! Bene, da oggi in poi giuro che sarò un uomo nuovo!"},{"a":"sia","t":"Grazie per la comprensione. Ora devo congedarmi."},{"a":"king","t":"La mia volontà è ferrea! Non mi servono beni materiali!"},{"a":"king","t":"... Anche se in questa stanza si sente davvero la mancanza di qualche <c1>lama regale</c1>, vero?"}]},{"id":"sia_05","i":5,"title":"Agente Swan","req":"sia:5","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"...La situazione ha preso una svolta drastica: re Reinhold è stato vittima di un tentativo di assassinio."},{"a":"sia","t":"Sembra che dietro il gesto ci sia Azuma. L'agente Swan svolgerà ulteriori indagini."},{"a":"king","t":"Sia! Cosa stai facendo?"},{"a":"sia","t":"Oh, niente di che. Stavo solo scrivendo una lettera."},{"a":"sia","t":"(In realtà è il mio rapporto all'imperatore di Kern...)"},{"a":"king","t":"Molto bene! Dei dignitari stranieri mi hanno chiesto udienza."},{"a":"king","t":"È possibile che siano leggermente offesi da quello che è successo nel corso dell'ultimo giro di acquisti."},{"a":"king","t":"Vorrei che mi aiutassi a calmare le acque!"},{"a":"sia","t":"Ma certo. La raggiungerò tra un momento, mio re."},{"a":"sia","t":"Informare l'imperatore di Kern dell'attentato contro il re potrebbe avere conseguenze nefaste..."},{"a":"sia","t":"Io... ho bisogno di più tempo per pensare. Questo regno non è ancora pronto ad affrontare Kern."},{"a":"sia","t":"Forse, per la sicurezza di tutti, sarebbe meglio omettere questo dettaglio..."},{"a":"sia","t":"Tutto procede secondo i piani. L'agente Swan non ha nulla da segnalare, questo mese."}]},{"id":"sia_06","i":6,"title":"Rosa e spine","req":"sia:6","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"king","t":"Sia! C'è un visitatore che chiede di te! Un tipo piuttosto principesco, devo dire."},{"a":"sia","t":"Principesco, vostra maestà? Non ditemi che si tratta di..."},{"a":"donovan","t":"Lady Sia."},{"a":"sia","t":"... Donovan."},{"a":"sia","t":"Vostra maestà, una faccenda urgente richiede la vostra presenza nella sala del tesoro. Consiglio di non indugiare."},{"a":"king","t":"Oh, è arrivato l'ultimo carico di Oro puro? Mi precipito!"},{"a":"donovan","t":"Il re non delude mai, vero?"},{"a":"sia","t":"Qual cattivo vento ti porta nel regno di Reinhold, alchimista?"},{"a":"donovan","t":"Come sempre dritta al punto, agente Swan."},{"a":"donovan","t":"Sono semplicemente in vacanza. Con il permesso dell'imperatore di Kern, naturalmente."},{"a":"donovan","t":"Annusare fiori, saggiare pozioni... Una classica vacanza da alchimista."},{"a":"sia","t":"E perché hai deciso di venire proprio qui, tra tutti i luoghi possibili?"},{"a":"donovan","t":"Stranamente questo regno malandato sembra ospitare un buon numero di abili alchimisti."},{"a":"donovan","t":"Certo, se dovessi notare che la lealtà di una certa persona sembra vacillare..."},{"a":"sia","t":"Non serve aggiungere altro, Donovan. Goditi pure la tua... vacanza."},{"a":"donovan","t":"Certamente, lady Sia. È stato, come sempre, un piacere."},{"a":"sia","t":"Un'altra spina nel mio fianco..."}]},{"id":"sia_07","i":7,"title":"Incontri nella Città d'oro","req":"sia:7","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"Donovan? Spero di non aver interrotto nulla di... spionistico."},{"a":"donovan","t":"Oh! Lady Sia!"},{"a":"donovan","t":"Nient'affatto! Stavo solo dando uno sguardo."},{"a":"sia","t":"Non serve essere così riservati. Tutti sono i benvenuti nella Città d'oro perduta."},{"a":"sia","t":"Ma ricorda che, per editto reale, tutto l'<c1>Oro puro</c1> trovato appartiene a re Reinhold."},{"a":"sia","t":"In cambio, gli arditi avventurieri vengono ricompensati per i loro ritrovamenti."},{"a":"donovan","t":"Capisco. Un sovrano davvero... generoso."},{"a":"donovan","t":"L'<c1>Oro puro</c1> viene poi usato per coniare moneta, causando una feroce inflazione..."},{"a":"sia","t":"Esatto. Vedo che hai intercettato le missive che ho inviato all'imperatore."},{"a":"donovan","t":"Mi piace tenermi aggiornato."},{"a":"sia","t":"Visto che sei qui, renditi utile e porta un po' di <c1>Oro puro</c1> al castello."},{"a":"donovan","t":"Con piacere. Il minimo, per la mia lady."},{"a":"sia","t":"Occhio a non spezzarti le unghie lungo la strada, Donovan caro."}]},{"id":"sia_08","i":8,"title":"Incrocio del fato","req":"sia:8","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"tavern","t":"Il mio piccolo cigno fa ritorno! Puntuale come sempre, come ci si aspetta dalla nostra eccelsa amministratrice."},{"a":"sia","t":"Ho risposto alla tua chiamata, Naya la ficcanaso. Sono di pessimo umore, ti prego di non perdere tempo."},{"a":"tavern","t":"Oh, temo che il tuo umore peggiorerà! Ho intercettato il messaggio di un certo alchimista..."},{"a":"tavern","t":"Un magimessaggio celere, per di più! Non hai idea di quanto siano sfuggenti!"},{"a":"sia","t":"Non vuoi mica dire che..."},{"a":"tavern","t":"Sembrerebbe che questo Donovan abbia scoperto i tuoi giochetti."},{"a":"sia","t":"Ma se hai intercettato il messaggio, allora..."},{"a":"tavern","t":"Già, non arriverà mai al destinatario. Sempre che tu sia disposta a pagare, ovviamente."},{"a":"sia","t":"Io... D'accordo. Dimmi quanto, Naya, e pagherò."},{"a":"tavern","t":"Purtroppo ho dovuto alzare i prezzi per l'inflazione. Ti costerà una taglia speciale."},{"a":"sia","t":"Bene, allora vado..."},{"a":"tavern","t":"Scegli da che parte schierarti, Sia. Il prezzo è questo."},{"a":"sia","t":"..."},{"a":"tavern","t":"Fare il doppio gioco è come tessere una pericolosa ragnatela... Una nella quale sei caduta prigioniera."},{"a":"tavern","t":"Ovviamente, a seconda della tua risposta, potrei riuscire ad aiutarti..."}]},{"id":"sia_09","i":9,"title":"Catena di tradimento","req":"sia:9","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"Caro Donovan, avrei una richiesta da farti."},{"a":"donovan","t":"Oh? Sentiamo. Di che si tratta?"},{"a":"sia","t":"Vai dall'imperatore e digli che l'agente Swan è caduto in battaglia. Una tragica morte al servizio dell'impero."},{"a":"donovan","t":"C-Come, scusa?"},{"a":"sia","t":"Mi dimetto, Donovan. Cambio schieramento."},{"a":"sia","t":"E sarai tu a dare la notizia. Confermando la mia storia, sia chiaro."},{"a":"donovan","t":"T-Tutto ciò è oltraggioso! Questo è tradimento! Io non intendo..."},{"a":"sia","t":"Riflettici bene, Donovan. Non vorrai mica che il mondo intero entri in possesso della ricetta del tuo elisir di lunga vita?"},{"a":"donovan","t":"Ah, dunque è questo il tuo bluff, Sia? Non ho mai confidato a nessuno la ricetta. È impossibile che..."},{"a":"sia","t":"Com'era? Ali di un'efemera centenaria... Acqua dello Stige..."},{"a":"donovan","t":"M-Ma questa è..."},{"a":"sia","t":"Sono un bel po' di ingredienti... Sbaglio o c'è anche un goccio di vino, per dare sapore?"},{"a":"donovan","t":"S-Silenzio. SILENZIO! Non so con quali arti oscure tu abbia ottenuto queste informazioni..."},{"a":"sia","t":"A quanto pare, hai sottovalutato la mia rete di spie."},{"a":"donovan","t":"Ma starò al tuo gioco. Per questa volta."},{"a":"sia","t":"Non sai proprio perdere, eh? Mi sembra che le mie condizioni siano generose."},{"a":"sia","t":"Cos'è un piccolo tradimento in cambio del lavoro di una vita?"}]},{"id":"sia_10","i":10,"title":"Assistenza postuma","req":"sia:10","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"Agente Sussurro. Sono io."},{"a":"essence","t":"Yaaawn... Di già?"},{"a":"sia","t":"Le tue informazioni erano precise. Hai svolto un ottimo lavoro."},{"a":"essence","t":"Nulla... di che..."},{"a":"sia","t":"Donovan è sempre stato molto cauto, ma a quanto pare nulla può impedire a un fantasma di origliare!"},{"a":"essence","t":"Decisamente..."},{"a":"essence","t":"Sembrava... molto arrabbiato..."},{"a":"sia","t":"Come concordato, ciò che ti spetta verrà lasciato sulla tua tomba, come un'offerta."},{"a":"sia","t":"Ho anche aggiunto un piccolo extra. Tormenta Donovan ancora per un po' di tempo."},{"a":"essence","t":"Vengo pagata... per fare il fantasma. Splendido."}]},{"id":"sia_11","i":11,"title":"Un cigno libero","req":"sia:11","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"king","t":"Sia! Non resisto più! Tra quanto potrò finalmente far dono dei miei capricci al mondo?"},{"a":"sia","t":"Sono passati solo pochi giorni, maestà. Un po' di pazienza, per favore."},{"a":"king","t":"Ah! Cosa sono tutte queste scartoffie?"},{"a":"sia","t":"Certificati di nascita e altri documenti importanti che mi riguardano."},{"a":"sia","t":"Sembra che, per una strana coincidenza, i documenti relativi alla mia vita in questo regno siano spariti."},{"a":"sia","t":"Perciò sto compilando tutti i moduli necessari andando a memoria."},{"a":"king","t":"Ma certo! La mia più grande consigliera non può che essere una cittadina ufficiale del mio regno!"},{"a":"king","t":"Dai qua! Vi apporrò il sigillo reale senza indugio!"},{"a":"king","t":"Ecco fatto! Non ti sfugge nessun dettaglio, come sempre!"},{"a":"sia","t":"Grazie, maestà. Spero di servire il regno per molti anni a venire."},{"a":"king","t":"Lo spero anche io!"},{"a":"king","t":"Sia, stai piangendo? La burocrazia riesce a trasmetterti emozioni così potenti?"},{"a":"sia","t":"No, no. Stavo solo sbadigliando, è stata una noia mortale."},{"a":"sia","t":"Ma piuttosto, discutiamo di questi futuri capricci!"},{"a":"king","t":"Bene! Lascia che te lo dica, l'attuale situazione degli scudi è..."}]}]},{"id":"atlab_sokka","name":"Sokka","chapters":[{"id":"atlab_sokka_01","i":1,"title":"Il grande guerriero Sokka","req":"atlab_sokka:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"atlab_aang","t":"E ora... così!"},{"a":"tavern","t":"Oh, che bel trucco!"},{"a":"atlab_sokka","t":"Ugh. Lo fa ogni volta!"},{"a":"argon","t":"Ciao, Sokka... giusto? Sono Argon!"},{"a":"atlab_sokka","t":"Oh, ehi. Se ti interessano trucchi e dominio degli elementi, Aang è la persona giusta."},{"a":"argon","t":"Oh no. Non ne so molto di magia. Né di dominio degli elementi."},{"a":"argon","t":"A giudicare dal tuo equipaggiamento, devi essere stato un temibile guerriero."},{"a":"atlab_sokka","t":"T-Temibile guerriero?"},{"a":"atlab_sokka","t":"B-Beh, così è! Sono Sokka, il grande guerriero del gruppo dell'Avatar!"},{"a":"argon","t":"Lo sapevo! Avrai delle storie incredibili da raccontare!"},{"a":"atlab_sokka","t":"Puoi scommetterci! Ad esempio, durante l'assedio del Nord..."},{"a":"atlab_sokka","t":"Ed è così che la mia ragazza dell'epoca si trasformò nella luna."},{"a":"argon","t":"L-La luna?"},{"a":"atlab_sokka","t":"Già. Ma poi la flotta della Nazione del Fuoco..."},{"a":"atlab_sokka","t":"...e sbam! Ho mandato al tappetto quel gufo gigante nella biblioteca."},{"a":"argon","t":"Wow! Quel gufo era uno spirito potente, vero?"},{"a":"atlab_sokka","t":"Proprio così! Ma il gruppo dell'Avatar ne esce sempre vittorioso quando il sottoscritto è nei paraggi!"},{"a":"atlab_sokka","t":"A proposito, dov'è Aang?"},{"a":"argon","t":"Oh, è andato via circa un'ora fa."},{"a":"atlab_sokka","t":"Caspita! Ho perso la cognizione del tempo. Scusa, Argon, devo scappare!"}]},{"id":"atlab_sokka_02","i":2,"title":"Il grande fabbro Sokka","req":"atlab_sokka:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"blacksmith","t":"Lavorando duro, eh, Sokka?"},{"a":"atlab_sokka","t":"Ehi, Wallace. Grazie per avermi lasciato usare i tuoi strumenti!"},{"a":"blacksmith","t":"Tranquillo! Non mi aspettavo che fossi un artigiano così abile alla tua età!"},{"a":"atlab_sokka","t":"Quando uno è l'unico del gruppo a non saper dominare gli elementi, bisogna che compensi in altri modi."},{"a":"atlab_sokka","t":"Non mi capita tutti i giorni di poter usare degli strumenti di tale fattura..."},{"a":"atlab_sokka","t":"Finirò la manutenzione in un battibaleno!"},{"a":"blacksmith","t":"Quella spada che stai affilando... Dove l'hai presa?"},{"a":"atlab_sokka","t":"È la mia spada spaziale! L'ho forgiata con le mie mani!"},{"a":"blacksmith","t":"Metallo stellare? Niente male, ragazzo."},{"a":"blacksmith","t":"Dev'essere... di un altro mondo!"},{"a":"atlab_sokka","t":"Puoi dirlo forte! La mia spada è unica e ultraterrena!"},{"a":"polonia","t":"Ahrrr! Scusate l'interruzione, ma non è che uno di voi ha tempo e voglia di aiutarmi a riparare la mia nave?"},{"a":"polonia","t":"Può essere che oggi sia di cattivo umore. Ha urtato contro delle palle di ferro galleggianti e si è arenata..."},{"a":"blacksmith","t":"Sembra proprio una bella barcata di guai!"},{"a":"atlab_sokka","t":"Ehi, nessun problema, sono della Tribù dell'Acqua! Vedrò che posso fare. Scusa, Wallace, devo andare!"},{"a":"blacksmith","t":"Nel frattempo, riparerò il resto del tuo equipaggiamento. In bocca al lupo!"}]},{"id":"atlab_sokka_03","i":3,"title":"Il grande navigatore Sokka","req":"atlab_sokka:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"atlab_sokka","t":"Ecco, almeno così dovresti riuscire ad arrivare al porto in sicurezza."},{"a":"polonia","t":"Bella riparazione. Sembra proprio buona."},{"a":"atlab_sokka","t":"Il timone è tenuto insieme da pezzi di legno pescati in mare e strisce di stoffa ricavate dalla mia maglia."},{"a":"atlab_sokka","t":"Non la definirei \"buona\" ma \"alla buona\" o se vogliamo... \"alla Sokka\"."},{"a":"polonia","t":"Yo ho ho! Com'è che un lupacchiotto d'acqua dolce come te sa riparare imbarcazioni?"},{"a":"atlab_sokka","t":"La vita della Tribù dell'Acqua ruota attorno alle barche e alla pesca. Ho imparato a navigare ancor prima di muovere i primi passi."},{"a":"atlab_sokka","t":"Di recente, ho buttato giù dei progetti per far muovere i sottomarini sfruttando il dominio dell'acqua!"},{"a":"polonia","t":"Usi un gergo troppo da gente di terra. Che significa?"},{"a":"atlab_sokka","t":"È... ehm, una nave di metallo che naviga sott'acqua."},{"a":"polonia","t":"Mi sembra più che altro un modo per far finire dei poveri lupi di mare in bocca al kraken."},{"a":"engineer","t":"Ho appena sentito \"prototipo non testato e potenzialmente pericoloso\"?"},{"a":"atlab_sokka","t":"Ah, non esattamente..."},{"a":"engineer","t":"Mi piace il tuo stile. Vieni con me, nuovo arrivato."},{"a":"polonia","t":"Yo ho ho, si salpa! Leviamo l'ancora, prima che arrivino i cacciatori di taglie!"},{"a":"polonia","t":"Ahrrr, meglio evitare quelle palle di ferro galleggianti stavolta."}]},{"id":"atlab_sokka_04","i":4,"title":"Il grande inventore Sokka","req":"atlab_sokka:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"engineer","t":"Affascinante! Sarò sincero, però, il tuo progetto fa un po' acqua..."},{"a":"engineer","t":"Ma con un po' di olio di gomito, credo quel sottomarino possa funzionare!"},{"a":"atlab_sokka","t":"Geniale, vero? Lo sapevo!"},{"a":"atlab_sokka","t":"Ricorda però che è progettato per essere manovrato dai dominatori dell'acqua."},{"a":"engineer","t":"Minuzie, ragazzo mio, minuzie. Escogiteremo qualcosa."},{"a":"engineer","t":"Pensa! Con questo, potremmo esplorare il Tempio sommerso!"},{"a":"atlab_sokka","t":"Oh, non incamera molto ossigeno, quindi meglio non fare viaggi troppo lunghi."},{"a":"atlab_sokka","t":"Mi stai ascoltando?"},{"a":"engineer","t":"Non appoggiarti su quella grossa sfera di ferro."},{"a":"atlab_sokka","t":"Eh? Ops! Perché no?"},{"a":"engineer","t":"È un prototipo di bomba subacquea di mia invenzione. È molto sensibile."},{"a":"atlab_sokka","t":"Oh..."},{"a":"atlab_sokka","t":"Beh, ad ogni modo, fammi sapere come procede il prototipo."},{"a":"atlab_sokka","t":"Se funziona... sappiamo già come impiegarlo."}]}]},{"id":"leather","name":"Tamas","chapters":[{"id":"leather_farewell","i":0,"title":null,"req":null,"reward":null,"side":false,"lines":[{"a":"leather","t":"Ehi, ascolta, forse ho finito con questa cosa del campione."},{"a":"leather","t":"Molte più responsabilità di quanto pensassi, ti dico. Non ho quasi più tempo da dedicare al cuoio!"},{"a":"leather","t":"Magari ci riprovo l'anno prossimo, capito. Ci vediamo in città!"}]},{"id":"leather_01","i":1,"title":"Il Cuoio e l'Albero","req":"leather:1","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"leather","t":"Grazie per l'aiuto."},{"a":"argon","t":"Di nulla, Tamas! È un bel po' di cuoio!"},{"a":"leather","t":"Un bel bottino, oggi. Fai attenzione allo scalino, però."},{"a":"argon","t":"Sì, non è facile muoversi qui... Ahi!"},{"a":"leather","t":"Ahio!"},{"a":"argon","t":"Scusa, Tamas, tutto ok?"},{"a":"leather","t":"Ho sbattuto un po' la testa. Cioè, credo di star bene."},{"a":"leather","t":"... Ho appena avuto un colpo di genio."},{"a":"leather","t":"Devo andare. Cioè, è qualcosa di speciale."},{"a":"argon","t":"Uh, va bene! Felice di esserti utile!"},{"a":"argon","t":"... Ma cosa ne faccio di tutto questo cuoio sparpagliato?"}]},{"id":"leather_02","i":2,"title":"Predetto dalla profezia","req":"leather:2","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"leather","t":"... Ed è così che ho sbattuto la testa. Cioè, ho un piccolo bernoccolo qui."},{"a":"mana","t":"Chi parla può ascoltare, ma aiuto non può dare."},{"a":"mana","t":"I flussi di etere formulano una predizione, ma non si occupano di guarigione."},{"a":"leather","t":"È comunque magia, no? Andiamo, cioè, pensaci tu con le tue mani magiche."},{"a":"mana","t":"Non c'è alc..."},{"a":"mana","t":"...!!!"},{"a":"mana","t":"Questo... destino...! Travolgente...!"},{"a":"leather","t":"Siamo sicuri che abbia funzionato? Cioè, mi sento ancora un po' stordito."},{"a":"mana","t":"... Le mie scuse. È emersa una nuova visione che richiede meditazione."},{"a":"mana","t":"Cerca la Prescelta della Dea se sei... ferito. Chi parla deve partire subito."},{"a":"leather","t":"Ok, cioè, va bene. Farò una passeggiata, mi sento piuttosto forte ultimamente."}]},{"id":"leather_03","i":3,"title":"L'unione del campione","req":"leather:3","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"argon","t":"Uhm, c'è un nuovo campione in città."},{"a":"polonia","t":"Yo ho ho! Speriamo sia uno stallone!"},{"a":"leather","t":"Ehilà."},{"a":"polonia","t":"Per mille cirripedi! È uno scherzo?"},{"a":"lilu","t":"Tamas?! Quando..."},{"a":"leather","t":"Ho deciso di lanciarmi e diventare un campione. Cioè, non sembra così difficile."},{"a":"argon","t":"Uhm... Tamas, perché non ci dici cosa fai?"},{"a":"leather","t":"Faccio fuori mostri. E so anche fiutare oggetti di cuoio, cioè, per chilometri."},{"a":"polonia","t":"Ehi! Rubare roba è la MIA specialità, trovatene una tua!"},{"a":"leather","t":"Non è rubare, cioè, la gente li lascia in giro."},{"a":"lilu","t":"Le cose si faranno presto interessanti qui intorno!"},{"a":"polonia","t":"Arr, forse hai ragione..."}]},{"id":"leather_04","i":4,"title":"Eroe sconosciuto","req":"leather:4","reward":{"k":"tokens","id":"tokens","q":5,"n":"Gettoni della fortuna"},"side":false,"lines":[{"a":"sia","t":"Mio re, ho una notizia alquanto inusuale."},{"a":"king","t":"Sono tutt'orecchie, come sempre! Continua!"},{"a":"sia","t":"Eroi e carovane riferiscono che le strade sono più sicure che mai."},{"a":"sia","t":"I mostri non si fanno vedere spesso e sembrano troppo impauriti per attaccare."},{"a":"king","t":"Che notizia fantastica!"},{"a":"sia","t":"Tuttavia, non abbiamo una spiegazione per questo strano comportamento."},{"a":"sia","t":"Una cosa altrettanto strana è il crollo improvviso sul mercato dei beni in cuoio..."},{"a":"king","t":"Una coincidenza, ne sono certo! Banchettiamo e festeggiamo la lieta novella!"},{"a":"sia","t":"Forse, mio re... Forse."}]}]},{"id":"yami","name":"Yami","chapters":[{"id":"yami_01","i":1,"title":"La vagabonda azumana","req":"yami:1","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"monster_forest_Boss","t":"Eh eh eh! Che cosa abbiamo qui?"},{"a":"yami","t":"Umpf. Smamma, parassita."},{"a":"monster_forest_Boss","t":"Ma che maniere, signorina! E che strano gusto nel vestire!"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Ah! Puzzi di Azuma, il regno umano d'oriente!"},{"a":"monster_forest_Boss","t":"Che ci fai quaggiù, signorina?"},{"a":"monster_forest_Boss","t":"Armata fino ai denti e con la bocca serrata... non sarai mica un'assassina, vero?"},{"a":"yami","t":"..."},{"a":"monster_forest_Boss","t":"Eh eh! Lo sapevo! Stupidi umani, sempre ad ammazzarsi l'un l'altro!"},{"a":"yami","t":"...Hai ragione. Sono venuta fin qui per uccidere un re tiranno."},{"a":"monster_forest_Boss","t":"Beh! Non sei certo una brava assassina se racconti a tutti questa cosa! Perché me l'hai detto?"},{"a":"yami","t":"Perché non vivrai per raccontarlo a nessuno. Addio."},{"a":"monster_forest_Boss","t":"Eek!"},{"a":"yami","t":"...Re Reinhold, tu sei il prossimo."}]},{"id":"yami_02","i":2,"title":"Cacciare o essere cacciati","req":"yami:2","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"yami","t":"...Il castello è sorvegliato impeccabilmente."},{"a":"yami","t":"C'è una parola d'ordine che cambia ogni giorno..."},{"a":"yami","t":"Dei turni di pattuglia senza orario preciso..."},{"a":"yami","t":"Dovrò essere-"},{"a":"argon","t":"Ehi, laggiù! Tu, nei cespugli!"},{"a":"yami","t":"...!"},{"a":"argon","t":"Anche tu sei venuta qui per diventare un cavaliere?"},{"a":"argon","t":"Sia arriverà presto! Non c'è bisogno di nasconderti, guarda che è molto gentile!"},{"a":"yami","t":"Sia...!"},{"a":"yami","t":"Devo andare. Arrivederci."},{"a":"argon","t":"A-aspetta!"},{"a":"argon","t":"Wow! Una bomba di fumo?!"},{"a":"yami","t":"...Ho seminato quello sciocco."},{"a":"yami","t":"Se c'è qui Sia... il mio compito sarà molto arduo."},{"a":"yami","t":"Ma deve essere portato a termine. Non posso fallire."},{"a":"yami","t":"Per l'Ordine... e per mia sorella."}]},{"id":"yami_03","i":3,"title":"Punto di svolta","req":"yami:3","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"king","t":"Stimati abitanti del regno! Grazie a tutti per essere accorsi al mio sontuoso banchetto!"},{"a":"king","t":"Questa è anche un'ottima opportunità per ammirare la mia meravigliosa persona! Non perdete questa occasione!"},{"a":"yami","t":"(Tipico di un pomposo tiranno.)"},{"a":"sia","t":"Ehm, certo. Grazie per il discorso edificante, sua maestà."},{"a":"sia","t":"Ci siamo riuniti tutti qui, oggi, per festeggiare l'incredibile generosità del re."},{"a":"sia","t":"Nel corso dei mesi passati, egli ha donato svariati milioni in monete d'oro dai suoi forzieri..."},{"a":"sia","t":"...a moltissimi templi, scuole e orfanatrofi della zona."},{"a":"sia","t":"Siete tutti benvenuti a partecipare, e vi invitiamo a spargere la voce fra amici e parenti."},{"a":"sia","t":"Lunga vita a re Reinhold!"},{"a":"yami","t":"(Queste non sono le azioni di un tiranno.)"},{"a":"yami","t":"(No, l'Ordine non mi avrebbe mai mentito. Deve essere un trucco.)"},{"a":"yami","t":"Reinhold il tiranno, il tuo regno termina ora!"},{"a":"sia","t":"Uno shuriken! L'assassina azumana!"},{"a":"yami","t":"L'ho mancato!? Impossibile!"},{"a":"sia","t":"Guardie! Bloccate tutte le uscite! Catturate immediatamente questa donna!"}]},{"id":"yami_04","i":4,"title":"Riflesso","req":"yami:4","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"yami","t":"(Ho esitato... e fallito.)"},{"a":"yami","t":"(Possibile che l'Ordine mi abbia mentito?)"},{"a":"yami","t":"(Non ha importanza. Oramai sono sola.)"},{"a":"argon","t":"Finalmente ti ho trovata!"},{"a":"yami","t":"Lo sciocco cavaliere!"},{"a":"argon","t":"Ehi! Non sono qui per combattere!"},{"a":"yami","t":"Non cadrò nel tuo tranello, cane di Reinhold!"},{"a":"argon","t":"L'hai mancato di proposito, vero?"},{"a":"yami","t":"...!"},{"a":"argon","t":"Ti ho vista al banchetto. Mi è sembrato che ti dispiacesse di aver lanciato lo shuriken."},{"a":"argon","t":"Il re non è cattivo, sai? È un po' strano a volte, ma cerca di fare del suo meglio!"},{"a":"argon","t":"Non so chi ti abbia pagata per farlo, ma non credo siano brave persone..."},{"a":"argon","t":"E se tornassi al castello e ti scusassi? Sono cerca che Reinhold..."},{"a":"yami","t":"Scusarmi? Che ottusità."},{"a":"yami","t":"Ho bisogno di riflettere. Non seguirmi, se hai cara la vita."},{"a":"argon","t":"Non è una cattiva persona, ne sono certo."},{"a":"argon","t":"Ora devo fare rapporto a Sia..."},{"a":"argon","t":"Oh cielo, mi farà a pezzettini..."}]},{"id":"yami_05","i":5,"title":"Al chiaro di luna","req":"yami:5","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"fabric","t":"<sprite tint=1 name=Note1>Sole sulle chiome dei salici, luce di un'epoca antica<sprite tint=1 name=Note2>..."},{"a":"fabric","t":"<sprite tint=1 name=Note2>Della radura elfica dove noi... Iih!"},{"a":"yami","t":"Quella che senti sul collo è la punta della mia lama."},{"a":"yami","t":"Ti farò delle domande. Rispondi con sincerità e forse avrai salva la vita."},{"a":"fabric","t":"Aah! S-sì! Ti dirò qualsiasi co... ahi!"},{"a":"yami","t":"Silenzio."},{"a":"yami","t":"Lo stolto che chiamate \"re\"... Parlami di lui."},{"a":"fabric","t":"R-re Reinhold? È il sovrano di queste terre..."},{"a":"fabric","t":"È alquanto eccentrico, ma non si può negare che sia un uomo onesto e generoso."},{"a":"fabric","t":"...Difetta di esperienza, ma la sua nuova consigliera, Sia, compensa ampiamente le sue carenze!"},{"a":"yami","t":"Impossibile! Le tue sono le parole di un codardo, ma suonano sincere."},{"a":"yami","t":"C'è un oracolo in questa città?"},{"a":"fabric","t":"Certo! Serene, l'elfa che vive sulla collina!"},{"a":"fabric","t":"Una misteriosa straniera... Posso avere l'onore di conoscere il tuo nome? Ahi!"},{"a":"yami","t":"Qualche giorno fa, ti avrei ucciso senza pensarci due volte. Non sfidare la sorte."},{"a":"yami","t":"Torna alla tua vita insulsa e dimentica questa conversazione."},{"a":"fabric","t":"...Caspita, che incontro emozionante!"},{"a":"fabric","t":"Fanciulla vestita di nero... Ci rivedremo mai...?"}]},{"id":"yami_06","i":6,"title":"Pedina sacrificata","req":"yami:6","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"mana","t":"Un vento oscuro tradisce la presenza dell'Inseguitrice."},{"a":"yami","t":"Come...!?"},{"a":"mana","t":"L'Inseguitrice si muove con la leggerezza di una piuma, ma il terzo occhio vede il peso che le grava sul cuore."},{"a":"yami","t":"Basta indovinelli, oracolo. Ho bisogno di risposte."},{"a":"yami","t":"Sull'Ordine... Sulla mia famiglia."},{"a":"mana","t":"Una dispensatrice di morte viene qui in cerca di consigli. Cosa offre in cambio?"},{"a":"yami","t":"La tua vita."},{"a":"mana","t":"...E sia."},{"a":"mana","t":"<c1>L'Ordine azumano, nato per porre rimedio alle ingiustizie...</c1>"},{"a":"mana","t":"<c1>...Difensori dell'ordine vendutisi al miglior offerente...</c1>"},{"a":"mana","t":"<c1>...Per un compito insormontabile, una pedina viene sacrificata...</c1>"},{"a":"mana","t":"<c1>...Che trionfi o fallisca, l'Ordine ne uscirà vincitore.</c1>"},{"a":"yami","t":"Impossibile."},{"a":"mana","t":"Il messaggero ha parlato."},{"a":"yami","t":"IMPOSSIBILE!"},{"a":"mana","t":"..."},{"a":"mana","t":"Colei che insegue le ombre dovrà anche fare ammenda con la luce, prima o poi."}]},{"id":"yami_07","i":7,"title":"Pedina sacrificata","req":"yami:7","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"yami","t":"Devo prendere le mie cose e andarmene quanto prima."},{"a":"inn","t":"Ehilà, straniera misteriosa."},{"a":"yami","t":"Oste, ho pagato per il tuo silenzio."},{"a":"inn","t":"Non devi preoccuparti, la privacy è importante qui alla locanda dello Smeraldo!"},{"a":"inn","t":"Tuttavia, ci sono alcuni brutti ceffi che sembra stiano cercando te."},{"a":"yami","t":"(Agenti dell'Ordine? Così presto?)"},{"a":"inn","t":"Non hanno lasciato nomi, ma erano davvero dei loschi figuri. Amici tuoi?"},{"a":"yami","t":"Non più. Di' loro che sono morta. Praticamente è come se lo fossi."},{"a":"inn","t":"Devi sparire, eh? Me lo aspettavo. Ti ho preparato delle provviste per il viaggio."},{"a":"yami","t":"Grazie, oste. Ma non mi serviranno dove sto andando."}]},{"id":"yami_08","i":8,"title":"Sola andata","req":"yami:8","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"Verso Picco Gugliatetra, hai detto?"},{"a":"wood","t":"Sì, ho visto una ragazza simile a un ninja, come l'hai descritta tu. Sembrava avere molta fretta."},{"a":"sia","t":"Eccellente. Finalmente abbiamo trovato l'assassina."},{"a":"sia","t":"Radunerò una squadra e..."},{"a":"wood","t":"Sicura? Non penso sia necessario."},{"a":"sia","t":"Perché no, Gorza?"},{"a":"wood","t":"Una spedizione solitaria al Picco Gugliatetra è un suicidio. La ragazza non aveva provviste con sé."},{"a":"wood","t":"Non poteva non saperlo. Perfino Rudo non è tanto stupido da andare fin lì da solo."},{"a":"sia","t":"Davvero? Grazie, Gorza. Terrò questi elementi in considerazione."},{"a":"sia","t":"Pare che il problema si sia risolto da solo, ma..."},{"a":"sia","t":"... Non è una soluzione soddisfacente. Cosa stai tramando, assassina?"}]},{"id":"yami_09","i":9,"title":"Scontro di Gugliatetra (Yami)","req":"yami:9","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"argon","t":"Era destino. Una taglia ben più ricca di quella di un'arpia!"},{"a":"yami","t":"Fatti sotto. Questo posto sarà la tua tomba."},{"a":"argon","t":"Non sembri davvero convinta delle tue parole..."},{"a":"yami","t":"Hai ragione. Non mi importa più nulla di niente."},{"a":"yami","t":"Se davvero mi vuoi morta, lasciami qui a morire."},{"a":"argon","t":"Non lascerei mai qualcuno a morire! Ti riporterò da re Reinhold!"},{"a":"argon","t":"So che capirà! Ti porterò in spalla, se devo!"},{"a":"yami","t":"..."},{"a":"argon","t":"Forza, andiamo!"},{"a":"argon","t":"Ehi, ma sei tutta pelle e ossa! Da quant'è che non mangi?"},{"a":"yami","t":"..."},{"a":"argon","t":"Fai uno spuntino mentre riscendiamo, sarà un viaggio impegnativo!"}]},{"id":"yami_10","i":10,"title":"Dietro la linee nemiche","req":"argon:10","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"Guardie! Chiamate i rinforzi e tenetela d'occhio!"},{"a":"sia","t":"Argon, aspetta fuori mentre parliamo con questa... intrusa."},{"a":"argon","t":"Obbedisco!"},{"a":"sia","t":"Bene. Ti ascoltiamo, assassina."},{"a":"yami","t":"Già, giusto. Ero stata ingaggiata per eliminare un tiranno."},{"a":"yami","t":"O così credevo... Ma pare che in realtà sia solo un pagliaccio benintenzionato."},{"a":"king","t":"P-Pagliaccio!?"},{"a":"sia","t":"Perché la tua gente odia il nostro re?"},{"a":"yami","t":"Il mio Ordine agisce solo in nome della giustizia..."},{"a":"yami","t":"Ma pare fosse solo una bugia. E ora che ho fallito, daranno la caccia anche a me."},{"a":"yami","t":"Io... chiedo scusa. Accetterò il mio giusto castigo..."},{"a":"yami","t":"Ugh."},{"a":"king","t":"È svenuta!"},{"a":"sia","t":"È esausta e malnutrita..."},{"a":"sia","t":"Guardie! Voglio i nostri migliori medici al suo capezzale!"},{"a":"sia","t":"Che sia trattata al pari di un'ospite del re."}]},{"id":"yami_epilogue","i":11,"title":"Epilogo","req":"yami:10","reward":{"k":"gems","id":"gems","q":10,"n":"Gioielli"},"side":false,"lines":[{"a":"sia","t":"Uff... Uff... Venire da te è... una bella scalata..."},{"a":"yami","t":"Questa è la mia casa, ora."},{"a":"sia","t":"Perché non vieni a vivere in città? Hai ricevuto il perdono del re."},{"a":"yami","t":"Il mio clan probabilmente mi crede morta, e vorrei che le cose rimanessero così."},{"a":"sia","t":"Capisco. Mi assicurerò che tu riceva regolarmente provviste."},{"a":"sia","t":"Ad ogni modo, per il tuo prossimo incarico..."},{"a":"yami","t":"Altri sgherri dell'impero?"},{"a":"sia","t":"Esatto. Come sai, sua Maestà attira le ire di molti occhi invidiosi."},{"a":"sia","t":"In questo documento troverai informazioni sui tuoi bersagli."},{"a":"yami","t":"Sarà fatto."},{"a":"sia","t":"Non amo ammetterlo, ma ti credo."},{"a":"sia","t":"Ora devo andare. Il pensiero del viaggio di ritorno non mi rallegra..."},{"a":"yami","t":"Sia... Reinhold..."},{"a":"yami","t":"Grazie. Davvero."}]}]}];
